/* بيانات قسم أسماء الله الحسنى: تُحمَّل عند أول فتح للقسم */
window.ASMA = {"ch":[{"id":"asl","t":"ولله الأسماء الحسنى فادعوه بها","et":"To Allah belong the most beautiful names, so call on Him by them","d":"الأسماء الحسنى أسماء الله التي بلغت الغاية في الحسن، لأنها تدل على صفات كمال لا نقص فيها بوجه. أمر الله بدعائه بها، وتوعّد الذين يميلون بها عن حقها. وهي غير محصورة بعدد؛ فالحديث يذكر أن من أحصى تسعة وتسعين منها دخل الجنة، وليس فيه أنها لا تزيد على ذلك. وهذا القسم يجمع الأسماء التي جاء لفظها في القرآن الكريم، كلُّ اسم بآيته ومعناه وشرحه.","ed":"The beautiful names are the names of Allah that reach the utmost in beauty, since each indicates an attribute of perfection with no deficiency at all. Allah commanded us to call on Him by them and warned those who distort them. They are not limited to a number: the hadith says whoever enumerates ninety-nine of them enters Paradise, not that they are no more than that. This section gathers the names whose wording appears in the Quran, each with its verse, meaning and explanation.","ay":[{"t":"فادعوه بها","et":"Call on Him by them","r":[7,180],"n":"أمر بالدعاء بالأسماء الحسنى، ونهي عن الإلحاد فيها، وهو الميل بها عن معانيها الحقة أو تسمية الله بما لم يُسمِّ به نفسه.","en":"A command to call on Allah by the beautiful names and a warning against distorting them: turning them from their true meanings, or naming Allah with what He did not name Himself."},{"t":"ادعوا الله أو ادعوا الرحمن","et":"Call on Allah or call on the Most Merciful","r":[17,110],"n":"كل اسم من أسمائه دالّ على ذاته مع معنى خاص، فمن دعا بأيّها فقد دعا ربه، «أيّاً ما تدعوا فله الأسماء الحسنى».","en":"Each name points to His essence with a particular meaning, so whoever calls on Him by any of them has called on his Lord: whichever you call, to Him belong the most beautiful names."},{"t":"الله لا إله إلا هو له الأسماء الحسنى","et":"There is no god but Him; to Him belong the best names","r":[20,8],"n":"اقتران التوحيد بإثبات الأسماء الحسنى: لا يُعبد إلا من له الكمال المطلق في أسمائه وصفاته.","en":"Tawhid joined to affirming the beautiful names: none is worshipped but the One whose names and attributes are perfect without limit."},{"t":"هو الله الخالق البارئ المصور","et":"He is Allah, the Creator, the Maker, the Fashioner","r":[59,22,24],"n":"خاتمة سورة الحشر من أجمع المواضع لأسمائه تعالى؛ يسبّح له ما في السماوات والأرض وهو العزيز الحكيم.","en":"The close of Surat al-Hashr is among the richest passages of His names; all in the heavens and earth glorify Him, and He is the Almighty, the All-Wise."}]},{"id":"hadith","t":"حديث الأسماء الحسنى وفضل إحصائها","et":"The hadith of the beautiful names and the merit of enumerating them","d":"نصوص الأحاديث بلفظها من الكتب المضمّنة في مشكاة، مع درجة كل منها كما هي في المصدر. وأصل الباب حديث أبي هريرة في الصحيحين؛ أما سرد التسعة والتسعين في رواية الترمذي فمحل نظر عند المحققين.","ed":"The hadith wording verbatim from the books bundled in Mishkat, with each one's grading as given in the source. The foundation is the hadith of Abu Hurayrah in the two Sahihs; the listing of the ninety-nine names in al-Tirmidhi's report is disputed among the verifiers.","ay":[]},{"id":"dhat","t":"أسماء الذات والألوهية","et":"Names of the Essence and Divinity","d":"الله والإله والرب، والأحد والواحد والصمد، والحي القيوم، والأول والآخر والظاهر والباطن، والحق والغني: أسماء تقرّر ذات الله ووحدانيته وكماله وغناه المطلق.","ed":"Allah, al-Ilah and ar-Rabb; al-Ahad, al-Wahid and as-Samad; al-Hayy al-Qayyum; the First, the Last, the Manifest and the Hidden; al-Haqq and al-Ghani: names that establish His essence, oneness, perfection and absolute self-sufficiency.","ay":[]},{"id":"rahma","t":"أسماء الرحمة والمغفرة والجود","et":"Names of Mercy, Forgiveness and Generosity","d":"الرحمن الرحيم والغفور والتواب والعفو والرؤوف والودود والكريم والوهاب: ما يطمع فيه العبد من ربه كلما أذنب ورجع إليه.","ed":"The Most Merciful, the Forgiving, the Acceptor of Repentance, the Pardoner, the Kind, the Loving, the Generous and the Bestower: what a servant hopes for from his Lord whenever he sins and returns.","ay":[]},{"id":"ilm","t":"أسماء العلم والإحاطة والقرب","et":"Names of Knowledge, Encompassing and Nearness","d":"العليم والخبير واللطيف والسميع والبصير والشهيد والرقيب والحسيب والمحيط والحفيظ والقريب والمجيب: يعلم المؤمن بها أن ربه يراه ويسمعه ويجيبه.","ed":"The All-Knowing, All-Aware, Subtle, All-Hearing, All-Seeing, Witness, Watchful, Reckoner, All-Encompassing, Preserver, Near and Responsive: through them the believer knows his Lord sees him, hears him and answers him.","ay":[]},{"id":"qudra","t":"أسماء القدرة والعزة والملك والعلو","et":"Names of Power, Might, Sovereignty and Highness","d":"الملك والعزيز والجبار والمتكبر والقهار والقوي والمتين والقادر والمقتدر والعلي والأعلى والعظيم والكبير والمتعال والمجيد والحميد وذو الجلال والإكرام: تعظيم لله وتخويف من سطوته ورجاء في عزته.","ed":"The King, the Almighty, the Compeller, the Supreme, the Subduer, the Strong, the Firm, the Able, the All-Powerful, the Most High, the Magnificent, the Great, the Self-Exalted, the Glorious, the Praiseworthy and the Lord of Majesty and Honour: exalting Allah, fearing His might and hoping in His dignity.","ay":[]},{"id":"khalq","t":"أسماء الخلق والرزق والهداية والولاية","et":"Names of Creation, Provision, Guidance and Guardianship","d":"الخالق والبارئ والمصور والبديع والفاطر والرزاق والفتاح والهادي والوارث والجامع والنصير والمولى والولي والكافي والنور: أفعاله سبحانه في خلقه وتدبيره ورعايته.","ed":"The Creator, Maker, Fashioner, Originator, Provider, Opener, Guide, Inheritor, Gatherer, Helper, Master, Protecting Friend, Sufficient and the Light: His acts in His creation, management and care.","ay":[]},{"id":"kamal","t":"أسماء الكمال والسلامة والحكمة","et":"Names of Perfection, Peace and Wisdom","d":"القدوس والسلام والمؤمن والمهيمن والحكيم والحكم والمبين: تنزيه الله عن كل نقص، وإثبات حكمته وعدله وبيانه.","ed":"The Most Holy, the Source of Peace, the Granter of Security, the Guardian, the All-Wise, the Judge and the Manifest: declaring Allah free of all deficiency and affirming His wisdom, justice and clarity.","ay":[]}],"n":[{"id":"allah","c":"dhat","a":"الله","e":"Allah","r":[[59,22],[2,255]],"m":"العلم على الذات العلية، ومعناه المألوه المعبود الذي تألهه القلوب حباً وتعظيماً ورجاءً؛ وهو أصل أسمائه الحسنى، وتتبعه سائر الأسماء والصفات.","em":"The proper name of the Divine Essence: the One worshipped, whom hearts turn to in love, reverence and hope. It is the root of all His beautiful names, and the other names and attributes follow it.","q":{"bk":"saadi","s":59,"ay":22,"x":"فأخبر أنَّه {الله}: المألوه المعبودُ الذي {لا إله إلاَّ هو}: وذلك لكماله العظيم وإحسانه الشامل وتدبيره العامِّ، وكلُّ إله غيره ؛ فإنَّه باطلٌ لا يستحقُّ من العبادة مثقال ذرَّةٍ؛ لأنه فقيرٌ عاجزٌ ناقصٌ لا يملك لنفسه ولا لغيره شيئاً."}},{"id":"ilah","c":"dhat","a":"الإله","e":"Al-Ilah (The God)","r":[[2,163]],"m":"المعبود بحق، لا يستحق العبادة سواه؛ ومنه كلمة التوحيد «لا إله إلا الله».","em":"The one truly worshipped; none other deserves worship. From it comes the testimony of faith, \"There is no god but Allah\".","q":null},{"id":"rabb","c":"dhat","a":"الرب","e":"Ar-Rabb (The Lord)","r":[[1,2],[6,164]],"m":"المالك المدبّر المربّي لخلقه بنعمه، يخلقهم ويرزقهم ويصلح أحوالهم.","em":"The Owner, Sustainer and Nurturer of His creation: He creates them, provides for them and sets their affairs right.","q":{"bk":"saadi","s":1,"ay":2,"x":"{رب العالمين} الربُّ: هو المربي جميع العالمين، وهم من سوى الله بخلقه لهم، وإعداده لهم الآلات، وإنعامه عليهم بالنعم العظيمة، التي لو فقدوها لم يمكن لهم البقاء، فما بهم من نعمة فمنه تعالى."}},{"id":"ahad","c":"dhat","a":"الأحد","e":"Al-Ahad (The One)","r":[[112,1]],"m":"المنفرد بكماله لا شبيه له ولا نظير، فلا يتجزأ ولا يتعدد في ذاته ولا صفاته.","em":"The One alone in His perfection, with no likeness or equal; not divisible and not plural in His essence or attributes.","q":{"bk":"saadi","s":112,"ay":1,"x":"{هو اللَّه أحدٌ}؛ أي: قد انحصرت فيه الأحديَّة؛ فهو الأحد المنفرد بالكمال، الذي له الأسماء الحسنى والصفات الكاملة العليا والأفعال المقدَّسة، الذي لا نظير له ولا مثيل."}},{"id":"wahid","c":"dhat","a":"الواحد","e":"Al-Wahid (The Unique)","r":[[13,16],[14,48]],"m":"المتوحّد بالألوهية والربوبية والأسماء والصفات، لا شريك له في شيء منها.","em":"Alone in divinity, lordship, names and attributes, with no partner in any of them.","q":{"bk":"saadi","s":14,"ay":48,"x":"{وبرزوا}؛ أي: الخلائق من قبورهم إلى يوم بعثهم ونشورهم في محلٍّ لا يخفى منهم على الله شيء، {لله الواحد القهار}؛ أي: المنفرد بعظمته وأسمائه وصفاته وأفعاله العظيمة وقهره لكلِّ العوالم؛ فكلُّها تحت تصرُّفه وتدبيره؛ فلا يتحرَّك منها متحرِّك، ولا يسكنُ ساكنٌ إلاَّ بإذنِهِ."}},{"id":"samad","c":"dhat","a":"الصمد","e":"As-Samad (The Eternal Refuge)","r":[[112,2]],"m":"السيد الذي كمل في سؤدده، وتصمد إليه الخلائق في حوائجها وتفزع إليه في مطالبها، وهو الغني عنها.","em":"The Master perfect in lordship to whom all creatures turn for their needs and in distress, while He needs none of them.","q":{"bk":"saadi","s":112,"ay":2,"x":"{اللهُ الصمدُ}؛ أي: المقصود في جميع الحوائج؛ فأهل العالم العلويِّ والسفليِّ مفتقرون إليه غاية الافتقار، يسألونَه حوائجَهم، ويرغَبون إليه في مهمَّاتهم؛ لأنَّه الكامل في أوصافه، العليم الذي قد كمل في علمه، الحليم الذي [قد] كمل في حلمه، الرحيم الذي كمل في رحمته، الذي وسعت رحمتُه كلَّ شيءٍ ..."}},{"id":"hayy","c":"dhat","a":"الحي","e":"Al-Hayy (The Ever-Living)","r":[[2,255],[40,65]],"m":"ذو الحياة الكاملة الأزلية الأبدية التي لا يعتريها موت ولا نقص، ومنها تفيض كل حياة.","em":"The One of perfect, eternal life that no death or deficiency touches, and from whom all life flows.","q":{"bk":"saadi","s":40,"ay":65,"x":"{هو الحيُّ}: الذي له الحياة الكاملة التامةُ المستلزمةُ لما تستلزمه من صفاتِهِ الذاتيَّة التي لا تتمُّ حياته إلاَّ بها؛ كالسمع والبصر والقدرة والعلم والكلام وغير ذلك من صفات كمالِهِ ونعوتِ جلالِهِ."}},{"id":"qayyum","c":"dhat","a":"القيوم","e":"Al-Qayyum (The Self-Subsisting Sustainer)","r":[[2,255],[3,2]],"m":"القائم بنفسه، المقيم لغيره؛ فلا قيام لشيء إلا به، ولا غنى لأحد عنه.","em":"The One who stands by Himself and upholds all else; nothing subsists except through Him and none is independent of Him.","q":{"bk":"saadi","s":3,"ay":2,"x":"فأخبر تعالى أنه {الحي}؛ كامل الحياة {القيوم}؛ القائم بنفسه المقيم لأحوال خلقه"}},{"id":"awwal","c":"dhat","a":"الأول","e":"Al-Awwal (The First)","r":[[57,3]],"m":"الذي ليس قبله شيء، فوجوده أزلي لا ابتداء له.","em":"The One before whom there is nothing; His existence is eternal, without a beginning.","q":{"bk":"saadi","s":57,"ay":3,"x":"{هو الأولُ}: الذي ليس قبلَه شيءٌ. {والآخر}: الذي ليس بعدَه شيءٌ. {والظاهر}: الذي ليس فوقَه شيءٌ. {والباطن}: الذي ليس دونَه شيءٌ. {وهو بكلِّ شيءٍ عليمٌ}: قد أحاط علمُه بالظواهر والبواطن والسرائر والخفايا والأمور المتقدِّمة والمتأخِّرة."}},{"id":"akhir","c":"dhat","a":"الآخر","e":"Al-Akhir (The Last)","r":[[57,3]],"m":"الذي ليس بعده شيء، فهو الباقي بعد فناء خلقه، لا انتهاء له.","em":"The One after whom there is nothing; He remains after all creation perishes, without an end.","q":{"bk":"saadi","s":57,"ay":3,"x":"{هو الأولُ}: الذي ليس قبلَه شيءٌ. {والآخر}: الذي ليس بعدَه شيءٌ. {والظاهر}: الذي ليس فوقَه شيءٌ. {والباطن}: الذي ليس دونَه شيءٌ. {وهو بكلِّ شيءٍ عليمٌ}: قد أحاط علمُه بالظواهر والبواطن والسرائر والخفايا والأمور المتقدِّمة والمتأخِّرة."}},{"id":"zahir","c":"dhat","a":"الظاهر","e":"Az-Zahir (The Manifest)","r":[[57,3]],"m":"الذي ظهر فوق كل شيء بعلوّه وقهره، وظهرت دلائله في خلقه حتى لا يخفى على بصيرة.","em":"The One manifest above all things in His highness and dominion, whose signs in creation are clear to every insight.","q":{"bk":"saadi","s":57,"ay":3,"x":"{هو الأولُ}: الذي ليس قبلَه شيءٌ. {والآخر}: الذي ليس بعدَه شيءٌ. {والظاهر}: الذي ليس فوقَه شيءٌ. {والباطن}: الذي ليس دونَه شيءٌ. {وهو بكلِّ شيءٍ عليمٌ}: قد أحاط علمُه بالظواهر والبواطن والسرائر والخفايا والأمور المتقدِّمة والمتأخِّرة."}},{"id":"batin","c":"dhat","a":"الباطن","e":"Al-Batin (The Hidden, Intimately Near)","r":[[57,3]],"m":"الذي احتجب عن الأبصار، وأحاط علمه بالخفايا والبواطن، فلا يغيب عنه سرّ.","em":"The One veiled from sight whose knowledge encompasses every hidden thing; no secret is absent from Him.","q":{"bk":"saadi","s":57,"ay":3,"x":"{هو الأولُ}: الذي ليس قبلَه شيءٌ. {والآخر}: الذي ليس بعدَه شيءٌ. {والظاهر}: الذي ليس فوقَه شيءٌ. {والباطن}: الذي ليس دونَه شيءٌ. {وهو بكلِّ شيءٍ عليمٌ}: قد أحاط علمُه بالظواهر والبواطن والسرائر والخفايا والأمور المتقدِّمة والمتأخِّرة."}},{"id":"haqq","c":"dhat","a":"الحق","e":"Al-Haqq (The Truth)","r":[[22,6],[24,25]],"m":"الثابت وجوده وصفاته وأفعاله وقوله ووعده؛ وكل ما سواه يُعرف بحق به أو باطل عنه.","em":"The One whose existence, attributes, acts, word and promise are firmly real; everything else is true only through Him.","q":null},{"id":"ghani","c":"dhat","a":"الغني","e":"Al-Ghani (The Self-Sufficient)","r":[[2,263],[3,97]],"m":"الكامل في غناه، لا يحتاج إلى أحد من خلقه في شيء، وكل ما سواه فقير إليه.","em":"Perfect in His self-sufficiency: He needs nothing from any creature, while everything else is in need of Him.","q":{"bk":"saadi","s":2,"ay":263,"x":"{والله}؛ تعالى {غني}؛ عن صدقاتهم وعن جميع عباده {حليم}؛ مع كمال غناه وسعة عطاياه يحلم عن العاصين، ولا يعاجلهم بالعقوبة بل يعافيهم، ويرزقهم، ويدر عليهم خيره، وهم مبارزون له بالمعاصي."}},{"id":"rahman","c":"rahma","a":"الرحمن","e":"Ar-Rahman (The Most Gracious)","r":[[1,3],[55,1]],"m":"ذو الرحمة الواسعة التي وسعت كل شيء، فتعمّ المؤمن والكافر في الدنيا.","em":"The One of vast mercy that encompasses everything and reaches believer and unbeliever alike in this world.","q":{"bk":"saadi","s":1,"ay":3,"x":"{الله}: هو المألوه المعبود المستحق لإفراده بالعبادة، لما اتصف به من صفات الألوهية وهي:صفات الكمال.{الرحمن الرحيم}: اسمان دالان على أنه تعالى ذو الرحمة الواسعة العظيمة التي وسعت كل شيء، وعمت كل حي، وكتبها للمتقين المتبعين لأنبيائه ورسله؛ فهؤلاء لهم الرحمة المطلقة، ومن عداهم فله نصيب منها."}},{"id":"rahim","c":"rahma","a":"الرحيم","e":"Ar-Rahim (The Most Merciful)","r":[[1,3],[33,43]],"m":"ذو الرحمة الواصلة، يرحم بها من شاء من عباده، وهي الخاصة بالمؤمنين في الآخرة.","em":"The One whose mercy reaches those He wills; it is a special mercy for the believers, completed in the Hereafter.","q":{"bk":"saadi","s":1,"ay":3,"x":"{الله}: هو المألوه المعبود المستحق لإفراده بالعبادة، لما اتصف به من صفات الألوهية وهي:صفات الكمال.{الرحمن الرحيم}: اسمان دالان على أنه تعالى ذو الرحمة الواسعة العظيمة التي وسعت كل شيء، وعمت كل حي، وكتبها للمتقين المتبعين لأنبيائه ورسله؛ فهؤلاء لهم الرحمة المطلقة، ومن عداهم فله نصيب منها."}},{"id":"ghafur","c":"rahma","a":"الغفور","e":"Al-Ghafur (The Oft-Forgiving)","r":[[2,173],[39,53]],"m":"كثير المغفرة، يستر الذنوب ويتجاوز عنها فلا يؤاخذ بها.","em":"Abundant in forgiveness: He covers sins and passes over them without taking to account.","q":{"bk":"saadi","s":39,"ay":53,"x":"{إنَّه هو الغفورُ الرحيمُ}؛ أي: وصفُه المغفرةُ والرحمةُ وصفان لازمانِ ذاتيَّانِ لا تنفكُّ ذاتُه عنهما، ولم تزلْ آثارُهُما ساريةً في الوجود، مالئةً للموجودِ، تسحُّ يداه من الخيراتِ آناءَ الليل والنهار، ويوالي النِّعم على العبادِ والفواضلَ في السرِّ والجهار، والعطاءُ أحبُّ إليه من المنع، والرحمةُ سبقتِ الغضبَ وغلبْته."}},{"id":"ghaffar","c":"rahma","a":"الغفار","e":"Al-Ghaffar (The Ever-Forgiving)","r":[[38,66],[71,10]],"m":"المبالغ في المغفرة، يغفر الذنب مرة بعد مرة لمن عاد إليه تائباً.","em":"Intensely forgiving: He forgives sin again and again for whoever returns to Him in repentance.","q":{"bk":"saadi","s":38,"ay":66,"x":"{الغفَّارُ}: لجميع الذنوب؛ صغيرها وكبيرها، لمن تاب إليه وأقلع منها."}},{"id":"tawwab","c":"rahma","a":"التواب","e":"At-Tawwab (The Acceptor of Repentance)","r":[[2,37],[2,160]],"m":"يوفّق عبده للتوبة ثم يقبلها منه، ويرجع عليه بالرحمة كلما رجع إليه.","em":"He grants His servant success in repenting, then accepts it, and turns to him with mercy each time he returns.","q":{"bk":"saadi","s":2,"ay":37,"x":"{إنه هو التواب}؛ لمن تاب إليه وأناب."}},{"id":"afuww","c":"rahma","a":"العفو","e":"Al-Afuww (The Pardoner)","r":[[4,99],[22,60]],"m":"الذي يمحو الذنوب ويتجاوز عن السيئات، فلا أثر لها ولا مؤاخذة.","em":"The One who erases sins and passes over wrongdoing, leaving no trace and no reckoning.","q":{"bk":"saadi","s":4,"ay":99,"x":"{فأولئك عسى اللهُ أن يعفُوَ عنهم وكان الله عفوًّا غفوراً}، و {عسى} ونحوها واجب وقوعها من الله تعالى بمقتضى كرمِهِ وإحسانه."}},{"id":"rauf","c":"rahma","a":"الرؤوف","e":"Ar-Ra'uf (The Most Kind)","r":[[2,143],[3,30]],"m":"ذو الرأفة، وهي أرقّ الرحمة وأبلغها في دفع المكروه عن عباده.","em":"The One of tenderness, the gentlest and most intense form of mercy, in warding harm from His servants.","q":{"bk":"saadi","s":2,"ay":143,"x":"وقوله:{إن الله بالنَّاسِ لرءوفٌ رحيمٌ}؛ أي: شديد الرحمة بهم عظيمها، فمن رأفته ورحمته بهم أن يُتِمَّ عليهم نعمته التي ابتدأهم بها، وأن ميز عنهم من دخل في الإيمان بلسانه دون قلبه، وأن امتحنهم امتحاناً زاد به إيمانهم وارتفعت به درجتهم، وأن وجههم إلى أشرف البيوت وأجلها."}},{"id":"wadud","c":"rahma","a":"الودود","e":"Al-Wadud (The Most Loving)","r":[[85,14],[11,90]],"m":"الذي يحب أنبياءه وأولياءه ويحبونه، ويتودد إلى عباده بنعمه وبره.","em":"The One who loves His prophets and friends and is loved by them, and shows loving-kindness to His servants through His favours.","q":{"bk":"saadi","s":85,"ay":14,"x":"{الودودُ}: الذي يحبُّه أحبابه محبَّةً لا يشبهها شيءٌ؛ فكما أنَّه لا يشابهه شيءٌ في صفات الجلال والجمال والمعاني والأفعال؛ فمحبَّته في قلوب خواصِّ خلقه التابعة لذلك لا يشبِهُها شيءٌ من أنواع المحابِّ، ولهذا كانت محبَّتُه أصل العبوديَّة، وهي المحبَّة التي تتقدَّم جميع المحابِّ وتغلبها، وإن لم تكن غيرها تبعاً لها؛ كانت عذاباً على أهلها، وهو تعالى الودودُ الوادُّ لأحبابه؛ كما قال تعالى:{يُحِبُّهم ويحبُّونه}: والمودَّة هي المحبَّة الصافية."}},{"id":"barr","c":"rahma","a":"البر","e":"Al-Barr (The Source of Goodness)","r":[[52,28]],"m":"الواسع الإحسان والجود، كثير الخير والبر بعباده.","em":"Vast in goodness and generosity, abundant in kindness toward His servants.","q":{"bk":"saadi","s":52,"ay":28,"x":"{إنَّه هو البرُّ الرحيم}: فمن برِّه [بنا] ورحمته إيَّانا أنالَنا رضاه والجنة، ووقانا سخطه والنار."}},{"id":"halim","c":"rahma","a":"الحليم","e":"Al-Halim (The Forbearing)","r":[[2,235],[17,44]],"m":"الذي لا يعاجل بالعقوبة من عصاه، بل يمهل ويستر ويؤخر لعلّهم يرجعون.","em":"He who does not hasten to punish the disobedient, but gives respite and covers, so that they may return.","q":{"bk":"saadi","s":2,"ay":235,"x":"{واعلموا أن الله يعلم ما في أنفسكم}؛ أي: فانووا الخير ولا تنووا الشرَّ خوفاً من عقابه ورجاء لثوابه، {واعلموا أن الله غفور}؛ لمن صدرت منه الذنوب فتاب منها، ورجع إلى ربه، {حليم}؛ حيث لم يعاجل العاصينَ على معاصيهم مع قدرته عليهم."}},{"id":"shakur","c":"rahma","a":"الشكور","e":"Ash-Shakur (The Most Appreciative)","r":[[35,30],[64,17]],"m":"الذي يشكر القليل من العمل فيضاعف ثوابه، ويجازي على الإحسان بأضعافه.","em":"He appreciates even small deeds and multiplies their reward, repaying good many times over.","q":{"bk":"saadi","s":35,"ay":30,"x":"{إنَّه غفورٌ شكورٌ}: غفر لهم السيئاتِ، وقَبِلَ منهم القليل من الحسنات."}},{"id":"shakir","c":"rahma","a":"الشاكر","e":"Ash-Shakir (The Appreciative)","r":[[2,158],[4,147]],"m":"الذي يقبل الطاعة من عباده ويثيبهم عليها، فلا يضيع عنده مثقال ذرة.","em":"He accepts His servants' obedience and rewards it; not an atom's weight is lost with Him.","q":null},{"id":"karim","c":"rahma","a":"الكريم","e":"Al-Karim (The Generous)","r":[[27,40],[82,6]],"m":"كثير الخير والعطاء، يعطي بلا سؤال ويعفو مع القدرة، وهو الشريف في ذاته وصفاته.","em":"Abundant in goodness and giving: He gives unasked, pardons while able, and is noble in essence and attributes.","q":{"bk":"saadi","s":82,"ay":6,"x":"يقول تعالى معاتباً للإنسان المقصِّر في حقِّه المتجرِّئ على معاصيه: {يا أيُّها الإنسان ما غَرَّك بربِّك الكريم}: أتهاوناً منك في حقوقه؟"}},{"id":"akram","c":"rahma","a":"الأكرم","e":"Al-Akram (The Most Generous)","r":[[96,3]],"m":"الذي بلغ الغاية في الكرم، فكل كرم عند خلقه من فيض كرمه.","em":"The One who reaches the utmost in generosity; every generosity in creation overflows from His.","q":{"bk":"saadi","s":96,"ay":3,"x":"{اقرأ وربُّك الأكرمُ}؛ أي: كثير الصِّفات، واسعها، كثير الكرم والإحسان، واسع الجود"}},{"id":"wahhab","c":"rahma","a":"الوهاب","e":"Al-Wahhab (The Bestower)","r":[[3,8],[38,9]],"m":"كثير الهبات يعطي عطاء بلا عوض ولا استحقاق، ويهب لمن شاء ما شاء.","em":"He gives gifts abundantly, without return or entitlement, granting whomever He wills whatever He wills.","q":{"bk":"saadi","s":3,"ay":8,"x":"ولما كان المقام مقام انقسام إلى منحرفين ومستقيمين دعوا الله تعالى أن يثبتهم على الإيمان فقالوا: {8}{ربنا لا تزغ قلوبنا}؛ أي: لا تملها عن الحق إلى الباطل {بعد إذ هديتنا وهب لنا من لدنك رحمة} تصلح بها أحوالنا؛ {إنك أنت الوهاب}؛ أي: كثير الفضل والهبات."}},{"id":"wasi","c":"rahma","a":"الواسع","e":"Al-Wasi' (The All-Encompassing)","r":[[2,115],[2,247]],"m":"الذي وسع علمه وفضله ورحمته وقدرته كل شيء.","em":"His knowledge, bounty, mercy and power encompass everything.","q":{"bk":"saadi","s":2,"ay":115,"x":"وبكل حال فما استقبل جهة من الجهات خارجة عن ملك ربه {فثم وجه الله إن الله واسع عليم}؛ فيه إثبات الوجه لله تعالى على الوجه اللائق به تعالى، وإن لله وجهاً لا تشبهه الوجوه، وهو تعالى واسع الفضل والصفات عظيمها عليم بسرائركم ونياتكم، فمن سعته وعلمه، وسع لكم الأمر، وقبل منكم المأمور، فله الحمد والشكر."}},{"id":"tawl","c":"rahma","a":"ذو الطول","e":"Dhu at-Tawl (The Possessor of Bounty)","r":[[40,3]],"m":"صاحب الفضل والإنعام الواسع على عباده، المتفضل بنعمه.","em":"The Possessor of vast favour and grace, who bestows His blessings upon His servants.","q":{"bk":"saadi","s":40,"ay":3,"x":"{العليم}: بكل شيء، {غافرِ الذنبِ}: للمذنبين، {وقابلِ التَّوۡبِ}: من التائبين، {شديدِ العقابِ}: على من تجرَّأ على الذُّنوب ولم يَتُبْ منها، {ذي الطَّوۡلَ}؛ أي: التفضُّل والإحسان الشامل."}},{"id":"alim","c":"ilm","a":"العليم","e":"Al-'Alim (The All-Knowing)","r":[[2,29],[2,32]],"m":"الذي أحاط علمه بكل شيء ظاهراً وباطناً، ماضياً وحاضراً ومستقبلاً.","em":"His knowledge encompasses all things, outward and inward, past, present and future.","q":{"bk":"saadi","s":57,"ay":3,"x":"{وهو بكلِّ شيءٍ عليمٌ}: قد أحاط علمُه بالظواهر والبواطن والسرائر والخفايا والأمور المتقدِّمة والمتأخِّرة."}},{"id":"khabir","c":"ilm","a":"الخبير","e":"Al-Khabir (The All-Aware)","r":[[6,18],[67,14]],"m":"العالم ببواطن الأمور وحقائقها، لا تخفى عليه خافية.","em":"He knows the inner realities of things; nothing is hidden from Him.","q":{"bk":"saadi","s":6,"ay":18,"x":"{وهو الحكيم}: فيما أمَرَ به ونهى، وأثابَ وعاقبَ، وفيما خَلَقَ وقدَّر، {الخبير}: المطَّلع على السرائر والضمائر وخفايا الأمور، وهذا كلُّه من أدلة التوحيد."}},{"id":"latif","c":"ilm","a":"اللطيف","e":"Al-Latif (The Subtle, Most Gentle)","r":[[6,103],[67,14]],"m":"الذي يدرك الخفايا الدقيقة، ويوصل الخير لعباده من حيث لا يشعرون برفق وحكمة.","em":"He perceives the finest hidden things and brings good to His servants gently and wisely from where they do not expect.","q":{"bk":"saadi","s":6,"ay":103,"x":"{وهو اللطيف الخبير}؛ أي: الذي لَطُفَ علمه وخبرته ودقَّ حتى أدرك السرائر والخفايا والخبايا والبواطن، ومن لطفه أنه يسوقُ عبدَه إلى مصالح دينه، ويوصلها إليه بالطرق التي لا يشعر بها العبد ولا يسعى فيها، ويوصله إلى السعادة الأبدية والفلاح السرمديِّ من حيث لا يحتسب، حتى إنه يقدِّرُ عليه الأمورَ التي يكرهها العبدُ ويتألَّمُ منها ويدعو اللهَ أن يزيلَها؛ لعلمه أن دينَهُ أصلح؛ وأن كمالَه متوقِّفٌ عليها؛ فسبحان اللطيفِ لما يشاء الرحيم بالمؤمنين."}},{"id":"sami","c":"ilm","a":"السميع","e":"As-Sami' (The All-Hearing)","r":[[2,127],[17,1]],"m":"الذي أحاط سمعه بجميع المسموعات، سرّها وجهرها، ويسمع الدعاء فيجيب.","em":"His hearing encompasses everything audible, secret and open; He hears supplication and responds.","q":{"bk":"baghawi","s":2,"ay":127,"x":"قَوْلُهُ: ﴿رَبَّنَا تَقَبَّلْ مِنَّا﴾ فِيهِ إِضْمَارٌ أَيْ وَيَقُولَانِ: رَبَّنَا تَقَبَّلْ مِنَّا بِنَاءَنَا ﴿إِنَّكَ أَنْتَ السَّمِيعُ﴾ لِدُعَائِنَا ﴿الْعَلِيمُ﴾ بِنِيَّاتِنَا"}},{"id":"basir","c":"ilm","a":"البصير","e":"Al-Basir (The All-Seeing)","r":[[17,1],[42,11]],"m":"الذي أحاط بصره بجميع المبصرات، لا يخفى عليه شيء ولو دق وصغر.","em":"His sight encompasses everything visible; nothing escapes Him, however small or subtle.","q":{"bk":"saadi","s":42,"ay":11,"x":"{البصير}: يرى دبيبَ النملة السوداء، في الليلة الظلماء، على الصخرة الصمَّاء، ويرى سَرَيانَ القوتِ في أعضاء الحيوانات الصغيرةِ جدًّا، وسريانَ الماء في الأغصان الدقيقة."}},{"id":"shahid","c":"ilm","a":"الشهيد","e":"Ash-Shahid (The Witness)","r":[[4,33],[22,17]],"m":"المطّلع على كل شيء، الشاهد على أعمال عباده، لا يغيب عنه شيء.","em":"He is aware of everything and witness over His servants' deeds; nothing is absent from Him.","q":{"bk":"saadi","s":4,"ay":33,"x":"{إنَّ الله كان على كلِّ شيءٍ شهيداً}؛ أي: مطَّلعاً على كلِّ شيءٍ بعلمه لجميع الأمور وبصرِهِ لحركات عبادِهِ وسمعه لجميع أصواتهم."}},{"id":"raqib","c":"ilm","a":"الرقيب","e":"Ar-Raqib (The Watchful)","r":[[4,1],[5,117]],"m":"الحافظ المراقب لأحوال خلقه وأعمالهم، لا يغفل ولا ينام.","em":"He who guards and observes the state and deeds of His creation; He neither neglects nor sleeps.","q":{"bk":"ibnkathir","s":4,"ay":1,"x":"وَقَوْلُهُ: ﴿إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا﴾ أَيْ: هُوَ مُرَاقِبٌ لِجَمِيعِ أَعْمَالِكُمْ وَأَحْوَالِكُمْ كَمَا قَالَ: ﴿وَاللَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ﴾ [الْبُرُوجِ: ٩] ."}},{"id":"hasib","c":"ilm","a":"الحسيب","e":"Al-Hasib (The Reckoner, Sufficient)","r":[[4,6],[33,39]],"m":"الكافي لعباده، المحاسب لهم على أعمالهم بالعدل.","em":"He who suffices His servants and also calls them to account for their deeds with justice.","q":null},{"id":"muhit","c":"ilm","a":"المحيط","e":"Al-Muhit (The All-Encompassing)","r":[[41,54],[4,126]],"m":"الذي أحاط بكل شيء علماً وقدرة وقهراً، فلا يخرج شيء عن إحاطته.","em":"He encompasses all things in knowledge, power and dominion; nothing escapes His grasp.","q":{"bk":"baghawi","s":41,"ay":54,"x":"﴿أَلَا إِنَّهُمْ فِي مِرْيَةٍ مِنْ لِقَاءِ رَبِّهِمْ﴾ فِي شَكٍّ مِنَ الْبَعْثِ، ﴿أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُحِيطٌ﴾ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا."}},{"id":"hafiz","c":"ilm","a":"الحفيظ","e":"Al-Hafiz (The Preserver)","r":[[11,57],[34,21]],"m":"الذي يحفظ خلقه وأعمالهم وأرزاقهم، ويحفظ السماوات والأرض فلا يثقله حفظهما.","em":"He preserves His creation, their deeds and provisions, and keeps the heavens and earth without burden.","q":{"bk":"saadi","s":34,"ay":21,"x":"{وربُّك على كلِّ شيءٍ حفيظٌ}: يحفظُ العباد ويحفظُ عليهم أعمالهم، ويحفظُ تعالى جزاءَها؛ فيوفِّيهم إيَّاها كاملة موفرةً."}},{"id":"muqit","c":"ilm","a":"المقيت","e":"Al-Muqit (The Sustainer, The Powerful Witness)","r":[[4,85]],"m":"المقتدر الحفيظ على كل شيء، ويأتي بمعنى الذي يوصل الأقوات إلى خلقه.","em":"The One powerful over and preserving all things; the word also means He who delivers sustenance to His creatures.","q":{"bk":"saadi","s":4,"ay":85,"x":"وقرَّر ذلك بقوله:{وكان الله على كل شيء مُقيتاً}؛ أي: شاهداً حفيظاً حسيباً على هذه الأعمال، فيجازي كلاًّ ما يستحقُّه."}},{"id":"wakil","c":"ilm","a":"الوكيل","e":"Al-Wakil (The Trustee, Disposer of Affairs)","r":[[3,173],[6,102]],"m":"الذي يُفوَّض إليه الأمر فيكفي ويتولى شؤون عباده، وعليه التوكل.","em":"The One to whom affairs are entrusted; He suffices and manages the affairs of His servants, and in Him is trust placed.","q":{"bk":"saadi","s":6,"ay":102,"x":"{وهو على كل شيء وكيل}، أي: جميع الأشياء تحت وكالة الله وتدبيره خلقاً وتدبيراً وتصريفاً."}},{"id":"qarib","c":"ilm","a":"القريب","e":"Al-Qarib (The Near)","r":[[2,186],[11,61]],"m":"القريب من عباده بعلمه وإحاطته، وقريب من داعيه بإجابته وإثابته.","em":"Near to His servants by knowledge and encompassing, and near to the one who calls on Him by answering and rewarding.","q":{"bk":"saadi","s":2,"ay":186,"x":"فنزل {وإذا سألك عبادي عني فإني قريب}؛ لأنه تعالى الرقيب الشهيد المطلع على السر وأخفى يعلم خائنةَ الأعين وما تخفي الصدور فهو قريب أيضاً من داعيه بالإجابة، ولهذا قال:{أجيب دعوة الداع إذا دعان}؛ والدعاء نوعان: دعاء عبادة، ودعاء مسألة."}},{"id":"mujib","c":"ilm","a":"المجيب","e":"Al-Mujib (The Responsive)","r":[[11,61],[37,75]],"m":"الذي يجيب دعوة الداعي إذا دعاه، ويعطي السائل سؤله.","em":"He answers the call of the one who calls on Him and grants the petitioner what he asks.","q":{"bk":"saadi","s":11,"ay":61,"x":"{إنَّ ربِّي قريبٌ مجيبٌ}؛ أي: قريبٌ ممَّن دعاه دعاء مسألة أو دعاء عبادة يجيبه بإعطائِهِ سؤاله وقَبول عبادتِهِ وإثابته عليها أجلَّ الثواب."}},{"id":"malik","c":"qudra","a":"الملك","e":"Al-Malik (The King)","r":[[59,23],[20,114]],"m":"صاحب الملك التام والتصرف المطلق في خلقه، يأمر وينهى ويحكم.","em":"Possessor of complete sovereignty and absolute disposal over His creation: He commands, forbids and rules.","q":{"bk":"saadi","s":20,"ay":114,"x":"{الملكُ}: الذي المُلْكُ وصفُه، والخلق كلُّهم مماليك له، وأحكام المُلْك القدريَّة والشرعيَّة نافذة فيهم."}},{"id":"malikmulk","c":"qudra","a":"مالك الملك","e":"Malik al-Mulk (Owner of Sovereignty)","r":[[3,26]],"m":"الذي بيده الملك كله، يؤتيه من يشاء وينزعه ممن يشاء.","em":"He in whose hand is all sovereignty; He gives it to whom He wills and takes it from whom He wills.","q":{"bk":"baghawi","s":3,"ay":26,"x":"قَوْلُهُ تَعَالَى ﴿قُلِ اللَّهُمَّ مَالِكَ الْمُلْكِ﴾ قَالَ قَتَادَةُ ذُكِرَ أَنَّ النَّبِيَّ ﷺ سَأَلَ رَبَّهُ أَنْ يَجْعَلَ مُلْكَ فَارِسَ وَالرُّومِ فِي أُمَّتِهِ فَأَنْزَلَ اللَّهُ تَعَالَى هَذِهِ الْآيَةَ."}},{"id":"aziz","c":"qudra","a":"العزيز","e":"Al-'Aziz (The Almighty)","r":[[59,23],[3,6]],"m":"الغالب الذي لا يُغلب، القوي الذي لا يُقهر، المنيع الذي لا يُنال.","em":"The Prevailing who is never overcome, the Strong who is never subdued, the Inaccessible who is never reached.","q":{"bk":"saadi","s":59,"ay":23,"x":"{العزيز}: الذي لا يغالَب ولا يمانَع، بل قد قهر كلَّ شيءٍ، وخضع له كلُّ شيءٍ. {الجبار}: الذي قهر جميع العباد، وأذعن له سائرُ الخلق، الذي يجبرُ الكسيرَ ويغني الفقير."}},{"id":"jabbar","c":"qudra","a":"الجبار","e":"Al-Jabbar (The Compeller)","r":[[59,23]],"m":"الذي يقهر خلقه على ما أراد، ويجبر الكسير ويُصلح الحال، العالي فوق خلقه.","em":"He who compels creation to what He wills, mends the broken and sets conditions right, high above His creatures.","q":{"bk":"saadi","s":59,"ay":23,"x":"{الجبار}: الذي قهر جميع العباد، وأذعن له سائرُ الخلق، الذي يجبرُ الكسيرَ ويغني الفقير. {المتكبِّر}: الذي له الكبرياء والعظمة، المتنزِّه عن جميع العيوب والظُّلم والجور."}},{"id":"mutakabbir","c":"qudra","a":"المتكبر","e":"Al-Mutakabbir (The Supreme in Greatness)","r":[[59,23]],"m":"المتعالي عن صفات النقص، الذي له الكبرياء وحده؛ وتكبّر غيره مذموم.","em":"He who is exalted above all deficiency and to whom greatness belongs alone; in others, pride is blameworthy.","q":{"bk":"saadi","s":59,"ay":23,"x":"{المتكبِّر}: الذي له الكبرياء والعظمة، المتنزِّه عن جميع العيوب والظُّلم والجور. {سبحان الله عمَّا يشركونَ}: وهذا تنزيهٌ عامٌّ عن كلِّ ما وصفه به من أشرك به وعانده."}},{"id":"qahhar","c":"qudra","a":"القهار","e":"Al-Qahhar (The Subduer)","r":[[13,16],[39,4]],"m":"الذي قهر كل شيء فذلّ له الخلق، وخضعت له الرقاب.","em":"He who has subdued all things; creatures are humbled before Him and necks bow to Him.","q":{"bk":"saadi","s":39,"ay":4,"x":"{هو الله الواحدُ القهَّارُ}؛ أي: الواحد في ذاته وفي أسمائه وفي صفاته وفي أفعاله؛ فلا شبيه له في شيء من ذلك ولا مماثل؛ فلو كان له ولدٌ؛ لاقتضى أن يكون شبيهاً له في وحدتِهِ؛ لأنَّه بعضُه وجزءٌ منه."}},{"id":"qahir","c":"qudra","a":"القاهر","e":"Al-Qahir (The Dominant)","r":[[6,18],[6,61]],"m":"الغالب على عباده بقدرته، فوقهم بقهره وعلوّه.","em":"He who overpowers His servants by His might, above them in dominion and highness.","q":{"bk":"saadi","s":6,"ay":18,"x":"{وهو القاهرُ فوق عبادِهِ}: فلا يتصرَّفُ منهم متصرِّف ولا يتحرَّك متحرِّك ولا يسكن ساكنٌ إلا بمشيئتِهِ، وليس للملوك وغيرهم الخروجُ عن ملكه وسلطانِهِ، بل هم مدبَّرون مقهورون؛ فإذا كان هو القاهرَ وغيرُه مقهوراً؛ كان هو المستحقَّ للعبادة."}},{"id":"qawi","c":"qudra","a":"القوي","e":"Al-Qawi (The Strong)","r":[[22,40],[11,66]],"m":"ذو القوة الكاملة التي لا يعتريها ضعف ولا عجز.","em":"The One of perfect strength that no weakness or incapacity touches.","q":{"bk":"saadi","s":11,"ay":66,"x":"{إنَّ ربَّك هو القويُّ العزيز}: ومن قوَّته وعزَّته أن أهلك الأممَ الطاغيةَ ونجَّى الرسلَ وأتباعهم. {67} وأخذت {الذين ظلموا الصيحة}: فقطعت قلوبهم؛ {فأصبحوا في ديارهم جاثمين}؛ أي: خامدين لا حراك لهم."}},{"id":"matin","c":"qudra","a":"المتين","e":"Al-Matin (The Firm)","r":[[51,58]],"m":"الشديد القوة الذي لا يلحقه تعب ولا لغوب.","em":"The One of intense strength whom no weariness or fatigue reaches.","q":null},{"id":"qadir","c":"qudra","a":"القادر","e":"Al-Qadir (The Able)","r":[[6,65],[46,33]],"m":"الذي له القدرة التامة على كل شيء، لا يعجزه شيء أراده.","em":"He has complete power over all things; nothing He wills defeats Him.","q":{"bk":"baghawi","s":6,"ay":65,"x":"قَوْلُهُ عَزَّ وَجَلَّ: ﴿قُلْ هُوَ الْقَادِرُ عَلَى أَنْ يَبْعَثَ عَلَيْكُمْ عَذَابًا مِنْ فَوْقِكُمْ﴾ قَالَ الْحَسَنُ وَقَتَادَةُ: نَزَلَتِ الْآيَةُ فِي أَهْلِ الْإِيمَانِ، وَقَالَ قَوْمٌ نَزَلَتْ فِي الْمُشْرِكِينَ."}},{"id":"muqtadir","c":"qudra","a":"المقتدر","e":"Al-Muqtadir (The All-Powerful)","r":[[54,42],[18,45]],"m":"البالغ في القدرة غايتها، الذي يقدّر الأمور ويُنفذها كما يشاء.","em":"He who reaches the utmost in power, who decrees matters and carries them out as He wills.","q":{"bk":"baghawi","s":54,"ay":42,"x":"﴿فَأَخَذْنَاهُمْ﴾ بِالْعَذَابِ ﴿أَخْذَ عَزِيزٍ﴾ غَالِبٍ فِي انْتِقَامِهِ ﴿مُقْتَدِرٍ﴾ قَادِرٍ عَلَى إِهْلَاكِهِمْ، لَا يُعْجِزُهُ مَا أَرَادَ، ثُمَّ خَوَّفَ أَهْلَ مَكَّةَ فَقَالَ: ﴿أَكُفَّارُكُمْ خَيْرٌ مِنْ أُولَئِكُمْ﴾ أَشَدُّ وَأَقْوَى مِنَ الَّذِينَ أَحْلَلْتُ بِهِمْ نِقْمَتِي مَنْ قَوْمِ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمِ لُوطٍ وَآلِ فِرْعَوْنَ؟"}},{"id":"ghalib","c":"qudra","a":"الغالب","e":"Al-Ghalib (The Prevailing)","r":[[12,21]],"m":"الذي لا يُردّ أمره ولا يُغلب، فإرادته نافذة.","em":"His command is never turned back nor overcome; His will is carried out.","q":{"bk":"saadi","s":12,"ay":21,"x":"{والله غالبٌ على أمرِهِ}؛ أي: أمره تعالى نافذٌ لا يبطله مبطلٌ ولا يغلبه مغالبٌ. {ولكنَّ أكثر الناس لا يعلمون}: فلذلك يجري منهم، ويصدُرُ ما يصدُرُ في مغالبة أحكام الله القدريَّة، وهم أعجز وأضعف من ذلك."}},{"id":"ali","c":"qudra","a":"العلي","e":"Al-'Ali (The Most High)","r":[[2,255],[42,4]],"m":"العالي بذاته فوق خلقه، وبقدره وصفاته، وبقهره وغلبته.","em":"The High in His essence above His creation, in His rank and attributes, and in His dominion and victory.","q":{"bk":"saadi","s":2,"ay":255,"x":"{وهو العلي}؛ بذاته على جميع مخلوقاته، وهو العلي بعظمة صفاته، وهو العلي الذي قهر المخلوقات، ودانت له الموجودات، وخضعت له الصعاب، وذلت له الرقاب {العظيم}؛ الجامع لجميع صفات العظمة والكبرياء والمجد والبهاء، الذي تحبه القلوب، وتعظمه الأرواح، ويعرف العارفون أن عظمة كل شيء وإن جلت عن الصفة فإنها مضمحلة في جانب عظمة العلي العظيم."}},{"id":"aala","c":"qudra","a":"الأعلى","e":"Al-A'la (The Most Exalted)","r":[[87,1],[20,68]],"m":"الذي لا أعلى منه، العالي في كل معنى من معاني العلو.","em":"There is none higher than Him; He is the highest in every sense of highness.","q":null},{"id":"azim","c":"qudra","a":"العظيم","e":"Al-'Azim (The Magnificent)","r":[[2,255],[56,96]],"m":"ذو العظمة والجلال، الذي تتضاءل دونه كل عظمة.","em":"The One of magnificence and majesty before whom every greatness is small.","q":{"bk":"saadi","s":2,"ay":255,"x":"{العظيم}؛ الجامع لجميع صفات العظمة والكبرياء والمجد والبهاء، الذي تحبه القلوب، وتعظمه الأرواح، ويعرف العارفون أن عظمة كل شيء وإن جلت عن الصفة فإنها مضمحلة في جانب عظمة العلي العظيم."}},{"id":"kabir","c":"qudra","a":"الكبير","e":"Al-Kabir (The Great)","r":[[13,9],[22,62]],"m":"الذي كبر عن كل شيء، فهو أعظم وأجلّ من أن يحيط به وصف.","em":"The One greater than everything, too great and majestic for any description to encompass Him.","q":{"bk":"saadi","s":13,"ay":9,"x":"{وكلُّ شيءٍ عنده بمقدارٍ}: لا يتقدَّم عليه ولا يتأخَّر ولا يزيد ولا يَنْقُص إلاَّ بما تقتضيه حكمته وعلمه؛ فإنَّه {عالمُ الغيب والشهادةِ الكبيرُ}: في ذاته وأسمائه وصفاته، {المتعالِ}: على جميع خلقه بذاتِهِ وقدرته وقهره."}},{"id":"mutaal","c":"qudra","a":"المتعال","e":"Al-Muta'al (The Self-Exalted)","r":[[13,9]],"m":"المنزّه عن كل نقص، العالي فوق خلقه علواً مطلقاً.","em":"He is exalted above every deficiency and absolutely high above His creation.","q":{"bk":"saadi","s":13,"ay":9,"x":"{وكلُّ شيءٍ عنده بمقدارٍ}: لا يتقدَّم عليه ولا يتأخَّر ولا يزيد ولا يَنْقُص إلاَّ بما تقتضيه حكمته وعلمه؛ فإنَّه {عالمُ الغيب والشهادةِ الكبيرُ}: في ذاته وأسمائه وصفاته، {المتعالِ}: على جميع خلقه بذاتِهِ وقدرته وقهره."}},{"id":"majid","c":"qudra","a":"المجيد","e":"Al-Majid (The Glorious)","r":[[85,15],[11,73]],"m":"ذو المجد والعظمة والجلال وسعة الفضل والكرم.","em":"Possessor of glory, greatness, majesty and vast bounty and generosity.","q":{"bk":"saadi","s":85,"ay":15,"x":"{ذو العرش المجيدُ}؛ أي: صاحب العرش العظيم، الذي من عظمته أنه وسع السماواتِ والأرض والكرسيَّ؛ فهي بالنسبة إلى العرش كحلقة ملقاةٍ في فلاةٍ بالنسبة لسائر الأرض ، وخصَّ الله العرش بالذِّكر لعظمته، ولأنَّه أخصُّ المخلوقات بالقرب منه [تعالى]."}},{"id":"hamid","c":"qudra","a":"الحميد","e":"Al-Hamid (The Praiseworthy)","r":[[14,8],[31,26]],"m":"المستحق للحمد في ذاته وأسمائه وصفاته وأفعاله.","em":"He is worthy of praise in His essence, names, attributes and acts.","q":{"bk":"baghawi","s":14,"ay":8,"x":"﴿وَقَالَ مُوسَى إِنْ تَكْفُرُوا أَنْتُمْ وَمَنْ فِي الْأَرْضِ جَمِيعًا فَإِنَّ اللَّهَ لَغَنِيٌّ حَمِيدٌ﴾ أَيْ: غَنِيٌّ عَنْ خَلْقِهِ، حَمِيدٌ: مَحْمُودٌ فِي أَفْعَالِهِ، لِأَنَّهُ فِيهَا مُتَفَضِّلٌ وَعَادِلٌ."}},{"id":"jalal","c":"qudra","a":"ذو الجلال والإكرام","e":"Dhu al-Jalali wal-Ikram (Lord of Majesty and Honour)","r":[[55,27],[55,78]],"m":"صاحب العظمة التي تُهاب، والكرم الذي يُرجى؛ فيُجَلّ ويُكرَم.","em":"Possessor of the majesty that is revered and the generosity that is hoped for; He is exalted and honoured.","q":{"bk":"saadi","s":55,"ay":27,"x":"أي: كلُّ مَن على الأرض من إنسٍ وجنٍّ ودوابٍّ وسائر المخلوقات يفنى [ويموت] ويبيد، ويبقى الحيُّ الذي لا يموت، {ذو الجلال والإكرام}؛ أي: ذو العظمة والكبرياء والمجد، الذي يعظَّم ويبجَّل ويجلُّ لأجله، والإكرام الذي هو سعة الفضل والجود، الذي يكرم أولياءه وخواصَّ خلقه بأنواع الإكرام، الذي يكرِمُه أولياؤه ويجلُّونه ويعظِّمونه ويحبُّونه وينيبون إليه ويعبدونه."}},{"id":"khaliq","c":"khalq","a":"الخالق","e":"Al-Khaliq (The Creator)","r":[[59,24],[6,102]],"m":"الذي أوجد الأشياء من العدم على تقدير سابق، لا خالق سواه.","em":"He who brought things into being from nothing according to prior measure; there is no creator besides Him.","q":{"bk":"baghawi","s":59,"ay":24,"x":"﴿هُوَ اللَّهُ الْخَالِقُ﴾ الْمُقَدِّرُ وَالْمُقَلِّبُ لِلشَّيْءِ بِالتَّدْبِيرِ إِلَى غَيْرِهِ، كَمَا قَالَ: \"يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ\" [الزمر: ٦] ﴿الْبَارِئُ﴾ الْمُنْشِئُ لِلْأَعْيَانِ مِنَ الْعَدَمِ إِلَى الْوُجُودِ ﴿الْمُصَوِّرُ﴾ الْمُمَثِّلُ لِلْمَخْلُوقَاتِ بِالْعَلَامَاتِ الَّتِي يَتَمَيَّزُ بَعْضُهَا عَنْ بَعْضٍ."}},{"id":"khallaq","c":"khalq","a":"الخلاق","e":"Al-Khallaq (The Perpetual Creator)","r":[[15,86],[36,81]],"m":"كثير الخلق والإبداع، لا ينقطع خلقه ولا ينفد.","em":"Abundant in creating and originating; His creation never ceases nor runs out.","q":{"bk":"saadi","s":15,"ay":86,"x":"{إنَّ ربَّك هو الخلاَّق}: لكل مخلوق، {العليمُ}: بكل شيءٍ؛ فلا يعجِزُه أحدٌ من جميع ما أحاط به علمُه، وجرى عليه خلقُه، وذلك سائر الموجودات."}},{"id":"bari","c":"khalq","a":"البارئ","e":"Al-Bari' (The Maker)","r":[[59,24]],"m":"الذي برأ الخلق وميّز بعضه عن بعض، فخلقه سالماً من التفاوت والخلل.","em":"He who produced creation and distinguished its kinds, creating it free of disproportion and flaw.","q":{"bk":"baghawi","s":59,"ay":24,"x":"﴿هُوَ اللَّهُ الْخَالِقُ﴾ الْمُقَدِّرُ وَالْمُقَلِّبُ لِلشَّيْءِ بِالتَّدْبِيرِ إِلَى غَيْرِهِ، كَمَا قَالَ: \"يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ\" [الزمر: ٦] ﴿الْبَارِئُ﴾ الْمُنْشِئُ لِلْأَعْيَانِ مِنَ الْعَدَمِ إِلَى الْوُجُودِ ﴿الْمُصَوِّرُ﴾ الْمُمَثِّلُ لِلْمَخْلُوقَاتِ بِالْعَلَامَاتِ الَّتِي يَتَمَيَّزُ بَعْضُهَا عَنْ بَعْضٍ."}},{"id":"musawwir","c":"khalq","a":"المصور","e":"Al-Musawwir (The Fashioner)","r":[[59,24]],"m":"الذي صوّر المخلوقات على ما شاء من الهيئات والأشكال، وأحسن صورها.","em":"He who forms creatures in whatever shapes He wills and makes their forms beautiful.","q":{"bk":"baghawi","s":59,"ay":24,"x":"﴿هُوَ اللَّهُ الْخَالِقُ﴾ الْمُقَدِّرُ وَالْمُقَلِّبُ لِلشَّيْءِ بِالتَّدْبِيرِ إِلَى غَيْرِهِ، كَمَا قَالَ: \"يَخْلُقُكُمْ فِي بُطُونِ أُمَّهَاتِكُمْ خَلْقًا مِنْ بَعْدِ خَلْقٍ\" [الزمر: ٦] ﴿الْبَارِئُ﴾ الْمُنْشِئُ لِلْأَعْيَانِ مِنَ الْعَدَمِ إِلَى الْوُجُودِ ﴿الْمُصَوِّرُ﴾ الْمُمَثِّلُ لِلْمَخْلُوقَاتِ بِالْعَلَامَاتِ الَّتِي يَتَمَيَّزُ بَعْضُهَا عَنْ بَعْضٍ."}},{"id":"badi","c":"khalq","a":"البديع","e":"Al-Badi' (The Originator)","r":[[2,117],[6,101]],"m":"الذي ابتدع الخلق على غير مثال سابق، وأبدع في خلقه.","em":"He who originated creation without a prior model and excelled in making it.","q":{"bk":"saadi","s":2,"ay":117,"x":"ثم قال: {117}{بديع السموات والأرض}؛ أي: خالقهما على وجه قد أتقنهما وأحسنهما على غير مثال سبق، {وإذا قضى أمراً فإنما يقول له كن فيكون}؛ فلا يستعصي عليه ولا يمتنع منه."}},{"id":"fatir","c":"khalq","a":"الفاطر","e":"Al-Fatir (The Originator of the Heavens and Earth)","r":[[6,14],[35,1]],"m":"الذي شقّ العدم فأخرج الخلق وابتدأه، فاطر السماوات والأرض.","em":"He who split open non-existence and brought creation forth: the Originator of the heavens and the earth.","q":{"bk":"saadi","s":6,"ay":14,"x":"{قل} لهؤلاء المشركين بالله: {أغيرَ الله أتَّخِذُ وليًّا}: من هؤلاء المخلوقات العاجزة يتولاَّني وينصُرُني؛ فلا أتَّخذ من دونه تعالى وليًّا؛ لأنَّه {فاطر السموات والأرض}؛ أي: خالقهما ومدبِّرهما، {وهو يُطۡعِمُ ولا يُطۡعَمُ}؛ أي: وهو الرازق لجميع الخلق من غير حاجةٍ منه تعالى إليهم؛ فكيف يَليقُ أن أتَّخِذَ وليًّا غير الخالق الرازق الغني الحميد."}},{"id":"razzaq","c":"khalq","a":"الرزاق","e":"Ar-Razzaq (The Provider)","r":[[51,58],[22,58]],"m":"الذي يرزق جميع الخلق، كلٌّ بما يصلحه، لا رازق غيره.","em":"He provides for all creatures, each as suits it; there is no provider besides Him.","q":{"bk":"saadi","s":51,"ay":58,"x":"فما يريد {منهم من رزقٍ وما} يريدُ {أن يطعمونِ}: تعالى الغنيُّ المغني عن الحاجة إلى أحدٍ بوجه من الوجوه، وإنَّما جميع الخلق فقراءُ إليه في جميع حوائجهم ومطالبهم الضروريَّة وغيرها."}},{"id":"fattah","c":"khalq","a":"الفتاح","e":"Al-Fattah (The Opener, The Judge)","r":[[34,26]],"m":"الذي يفتح أبواب الرزق والرحمة لعباده، ويفتح بينهم بالحق فيقضي ويفصل.","em":"He opens the doors of provision and mercy for His servants, and opens between them with truth, judging and deciding.","q":{"bk":"saadi","s":34,"ay":26,"x":"ولهذا قال: {قل يَجۡمَعُ بينَنا ربُّنا ثم يفتحُ بينَنا}؛ أي: يحكم بينَنا حكماً يتبيَّن به الصادقُ من الكاذب، والمستحقُّ للثواب من المستحقِّ للعقاب وهو خير الفاتحين."}},{"id":"hadi","c":"khalq","a":"الهادي","e":"Al-Hadi (The Guide)","r":[[25,31],[22,54]],"m":"الذي يهدي من شاء إلى الحق، ويدلّ عباده على ما ينفعهم.","em":"He guides whom He wills to the truth and directs His servants to what benefits them.","q":null},{"id":"warith","c":"khalq","a":"الوارث","e":"Al-Warith (The Inheritor)","r":[[15,23]],"m":"الباقي بعد فناء الخلق، ترجع إليه الأملاك كلها بعد زوال أهلها.","em":"He remains after creation perishes; all possessions return to Him after their owners pass away.","q":{"bk":"saadi","s":15,"ay":23,"x":"أي: هو وحده لا شريك له الذي يحيي الخلق من العدم بعد أن لم يكونوا شيئاً مذكوراً، ويميتهم لآجالهم التي قدرها، {ونحن الوارثون}؛ كقوله:{إنا نحنُ نَرِثُ الأرضَ ومَنۡ عليها وإلينا يُرۡجَعون}: وليس ذلك بعزيز ولا ممتنع على الله؛ فإنه تعالى يعلم المستقدِمين من الخلق والمستأخِرين منهم، ويعلم ما تَنْقُصُ الأرض منهم وما تفرِّقُ من أجزائهم، وهو الذي قدرتُهُ لا يعجِزُها معجِزٌ، فيعيد عباده خلقاً جديداً، ويحشُرُهم إليه."}},{"id":"jami","c":"khalq","a":"الجامع","e":"Al-Jami' (The Gatherer)","r":[[3,9],[4,140]],"m":"الذي يجمع الخلائق ليوم الحساب، ويؤلّف بين المتفرقات.","em":"He who gathers creation for the Day of Reckoning and brings scattered things together.","q":{"bk":"baghawi","s":3,"ay":9,"x":"﴿رَبَّنَا إِنَّكَ جَامِعُ النَّاسِ لِيَوْمٍ﴾ أَيْ لِقَضَاءِ يَوْمٍ، وَقِيلَ: اللَّامُ بِمَعْنَى فِي، أَيْ فِي يَوْمٍ ﴿لَا رَيْبَ فِيهِ﴾ أَيْ لَا شَكَّ فِيهِ، وَهُوَ يَوْمُ الْقِيَامَةِ ﴿إِنَّ اللَّهَ لَا يُخْلِفُ الْمِيعَادَ﴾ مِفْعَالٌ مِنَ الْوَعْدِ."}},{"id":"nasir","c":"khalq","a":"النصير","e":"An-Nasir (The Helper)","r":[[8,40],[25,31]],"m":"الناصر لأوليائه، يؤيدهم ويغلب بهم أعداءه.","em":"He helps His friends, supports them and gives them victory over their enemies.","q":{"bk":"saadi","s":8,"ay":40,"x":"{ونعم النصيرُ}: الذي ينصُرُهم فيدفع عنهم كيدَ الفجَّار وتكالب الأشرار، ومَن كان الله مولاه وناصره؛ فلا خوفٌ عليه، ومَنْ كان الله عليه؛ فلا عزَّ له ولا قائمة له."}},{"id":"mawla","c":"khalq","a":"المولى","e":"Al-Mawla (The Patron and Master)","r":[[8,40],[2,286]],"m":"السيد المتولّي لأمور عباده، الناصر لهم والمتصرف فيهم.","em":"The Master who takes charge of His servants' affairs, helping them and disposing of them.","q":{"bk":"saadi","s":8,"ay":40,"x":"{وإن تولَّوا}: عن الطاعة، وأوضعوا في الإضاعة، {فاعلموا أنَّ الله مولاكم نعم المولى}: الذي يتولَّى عباده المؤمنين، ويوصِلُ إليهم مصالحهم وييسِّر لهم منافعهم الدينيَّة والدنيويَّة."}},{"id":"wali","c":"khalq","a":"الولي","e":"Al-Wali (The Protecting Friend)","r":[[42,9],[2,257]],"m":"المتولي لأمور عباده المؤمنين، يحبهم ويحفظهم ويخرجهم من الظلمات إلى النور.","em":"He who takes charge of His believing servants' affairs, loves and protects them, and brings them from darkness to light.","q":null},{"id":"kafi","c":"khalq","a":"الكافي","e":"Al-Kafi (The Sufficient)","r":[[39,36]],"m":"الذي يكفي عباده كل ما أهمهم، ولا يحتاجون معه إلى غيره.","em":"He suffices His servants in all that concerns them, and they need no one besides Him.","q":{"bk":"saadi","s":39,"ay":36,"x":"{أليسَ اللهُ بكافٍ عبدَه}؛ أي: أليس من كرمِهِ وجودِهِ وعنايتِهِ بعبده الذي قام بعبوديَّته وامتثل أمرَه واجتنب نهيَه، خصوصاً أكمل الخلق عبوديَّةً لربِّه، وهو محمدٌ - صلى الله عليه وسلم -؛ فإنَّ الله تعالى سيكفيه في أمر دينه ودُنياه ويدفعُ عنه من ناوأه بسوءٍ."}},{"id":"nur","c":"khalq","a":"النور","e":"An-Nur (The Light)","r":[[24,35]],"m":"الذي بنوره أضاءت السماوات والأرض، ومنه نور الهداية في القلوب.","em":"By His light the heavens and earth are illumined, and from Him comes the light of guidance in hearts.","q":{"bk":"saadi","s":24,"ay":35,"x":"{مَثَلُ نورِهِ}: الذي يهدي إليه، وهو نورُ الإيمان والقرآن في قلوب المؤمنين {كمشكاةٍ}؛ أي: كوَّة {فيها مصباحٌ}: لأنَّ الكوَّة تجمع نورَ المصباح بحيث لا يتفرَّق."}},{"id":"quddus","c":"kamal","a":"القدوس","e":"Al-Quddus (The Most Holy)","r":[[59,23],[62,1]],"m":"المنزّه عن كل عيب ونقص، الطاهر المبارك الكامل في صفاته.","em":"Free of every fault and deficiency, pure, blessed and perfect in His attributes.","q":{"bk":"saadi","s":59,"ay":23,"x":"{القدُّوسُ السلامُ}؛ أي: المقدَّس السالم من كل عيبٍ [وآفة] ونقص المعظَّم الممجَّد؛ لأنَّ القدوس يدلُّ على التنزيه من كل نقص والتعظيم لله في أوصافه وجلاله."}},{"id":"salam","c":"kamal","a":"السلام","e":"As-Salam (The Source of Peace)","r":[[59,23]],"m":"السالم من كل نقص وعيب، ومنه تفيض السلامة والأمان على خلقه.","em":"Safe from all deficiency and defect; from Him flow safety and security to His creation.","q":{"bk":"saadi","s":59,"ay":23,"x":"{القدُّوسُ السلامُ}؛ أي: المقدَّس السالم من كل عيبٍ [وآفة] ونقص المعظَّم الممجَّد؛ لأنَّ القدوس يدلُّ على التنزيه من كل نقص والتعظيم لله في أوصافه وجلاله."}},{"id":"mumin","c":"kamal","a":"المؤمن","e":"Al-Mu'min (The Granter of Security)","r":[[59,23]],"m":"الذي يؤمّن عباده من ظلمه، ويصدّق رسله بالآيات، ويُصدِّق وعده.","em":"He grants His servants security from His wronging, confirms His messengers with signs, and fulfils His promise.","q":{"bk":"saadi","s":59,"ay":23,"x":"{المؤمن}؛ أي: المصدِّق لرسله وأنبيائه بما جاؤوا به بالآيات البيِّنات والبراهين القاطعات والحجج الواضحات."}},{"id":"muhaymin","c":"kamal","a":"المهيمن","e":"Al-Muhaymin (The Guardian)","r":[[59,23],[5,48]],"m":"الرقيب الشاهد على خلقه الحافظ لهم، المسيطر على كل شيء.","em":"The Watcher and Witness over His creation, preserving them and holding sway over everything.","q":{"bk":"baghawi","s":59,"ay":23,"x":"﴿الْمُهَيْمِنُ﴾ الشَّهِيدُ عَلَى عِبَادِهِ بِأَعْمَالِهِمْ، وَهُوَ قَوْلُ ابْنِ عَبَّاسٍ، وَمُجَاهِدٍ وَقَتَادَةَ وَالسُّدِّيِّ وَمُقَاتِلٌ."}},{"id":"hakim","c":"kamal","a":"الحكيم","e":"Al-Hakim (The All-Wise)","r":[[2,32],[31,27]],"m":"الذي أحكم صنع كل شيء، ووضع الأمور في مواضعها، وله الحكمة البالغة.","em":"He made everything with perfect craft and put every matter in its proper place; His wisdom is complete.","q":{"bk":"saadi","s":2,"ay":32,"x":"{قالوا سبحانك}؛ أي ننزهك من الاعتراض منَّا عليك، ومخالفة أمرك {لا علم لنا}؛ بوجه من الوجوه، {إلا ما علمتنا}؛ إياه فضلاً منك وجوداً {إنك أنت العليم الحكيم}؛ العليم الذي أحاط علماً بكل شيء، فلا يغيب عنه ولا يعزب مثقال ذرة في السماوات والأرض ولا أصغر من ذلك ولا أكبر، الحكيم: من له الحكمة التامة التي لا يخرج عنها مخلوق ولا يشذ عنها مأمور، فما خلق شيئاً إلا لحكمة، ولا أمر بشيء إلا لحكمة، والحكمة وضع الشيء في موضعه اللائق به."}},{"id":"hakam","c":"kamal","a":"الحكم","e":"Al-Hakam (The Judge)","r":[[6,114],[40,12]],"m":"الذي له الحكم وحده، لا معقّب لحكمه، ويحكم بين عباده بالعدل.","em":"To Him alone belongs judgement, none can reverse His ruling, and He judges between His servants with justice.","q":{"bk":"saadi","s":40,"ay":12,"x":"{فالحكم لله العليِّ الكبير}: العلي: الذي له العلو المطلق من جميع الوجوه: علو الذات، وعلو القدر، وعلو القهر، ومن علو قدره كمالُ عدله تعالى، وأنَّه يضع الأشياء مواضعها، ولا يساوي بين المتقين والفجار."}},{"id":"mubin","c":"kamal","a":"المبين","e":"Al-Mubin (The Manifest)","r":[[24,25]],"m":"الذي يبيّن الحق ويظهره، وهو ظاهر الوجود والدلائل.","em":"He who makes the truth plain and manifest, evident in existence and in proofs.","q":null}],"h":[{"id":"ihsa","t":"من أحصى الأسماء الحسنى دخل الجنة","et":"Whoever enumerates the beautiful names enters Paradise","x":"إِنَّ لِلَّهِ تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً إِلاَّ وَاحِدًا، مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ","src":[["bukhari","7392"],["muslim","2677"]],"gr":"صحيح: متفق عليه","dg":"","f":"إحصاء الأسماء عند العلماء: حفظ ألفاظها، وفهم معانيها، والتعبد لله بمقتضاها، ودعاؤه بها. والعدد بيان لما من أحصاه نال هذا الفضل، وليس تحديداً لأسمائه تعالى.","ef":"Scholars explain \"enumerating\" as memorising their wording, understanding their meanings, worshipping Allah according to their requirements and calling on Him by them. The number states what earns this reward; it does not limit His names.","en":"Allah has ninety-nine names, one hundred less one; whoever enumerates them will enter Paradise.","ch":"hadith"},{"id":"watr","t":"لله تسعة وتسعون اسماً وهو وتر يحب الوتر","et":"Allah has ninety-nine names, and He is One who loves the odd","x":"لِلَّهِ تِسْعَةٌ وَتِسْعُونَ اسْمًا مَنْ حَفِظَهَا دَخَلَ الْجَنَّةَ وَإِنَّ اللَّهَ وِتْرٌ يُحِبُّ الْوِتْرَ","src":[["muslim","2677"]],"gr":"صحيح: رواه مسلم","dg":"","f":"وتأتي في الروايات ألفاظ «حفظها» و«أحصاها»، يفسّر بعضها بعضاً، ومقصودها واحد: القيام بحق الأسماء علماً وعملاً.","ef":"The reports use the words \"memorised\" and \"enumerated\", and each explains the other; the intent is the same: fulfilling the right of the names in knowledge and action.","en":"Allah has ninety-nine names; whoever memorises them enters Paradise. Allah is One and loves the odd number.","ch":"hadith"},{"id":"awwal","t":"اللهم أنت الأول فليس قبلك شيء","et":"O Allah, You are the First and nothing is before You","x":"اللَّهُمَّ أَنْتَ الأَوَّلُ فَلَيْسَ قَبْلَكَ شَىْءٌ وَأَنْتَ الآخِرُ فَلَيْسَ بَعْدَكَ شَىْءٌ وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَىْءٌ وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَىْءٌ اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ","src":[["muslim","2713"]],"gr":"صحيح: رواه مسلم","dg":"","f":"دعاء عند النوم يفسّر أربعة أسماء: الأول، والآخر، والظاهر، والباطن؛ فالدعاء بالأسماء يكون بعد تعظيم الله بمعانيها.","ef":"A bedtime supplication that explains four names: the First, the Last, the Manifest and the Hidden; calling on Allah by the names comes after glorifying Him with their meanings.","en":"O Allah, You are the First, nothing is before You; You are the Last, nothing is after You; You are the Manifest, nothing is above You; and You are the Hidden, nothing is nearer than You. Settle our debt and enrich us from poverty.","ch":"hadith"},{"id":"rahma","t":"لله مائة رحمة","et":"Allah has one hundred mercies","x":"إِنَّ لِلَّهِ مِائَةَ رَحْمَةٍ فَمِنْهَا رَحْمَةٌ بِهَا يَتَرَاحَمُ الْخَلْقُ بَيْنَهُمْ وَتِسْعَةٌ وَتِسْعُونَ لِيَوْمِ الْقِيَامَةِ","src":[["muslim","2753"]],"gr":"صحيح: رواه مسلم","dg":"","f":"يبيّن سعة اسمَي الرحمن والرحيم: رحمة واحدة تتراحم بها الخلائق كلها في الدنيا، وتسع وتسعون مدّخرة ليوم القيامة.","ef":"It shows the vastness of the names ar-Rahman and ar-Rahim: one mercy by which all creatures show compassion in this world, and ninety-nine kept for the Day of Resurrection.","en":"Allah has one hundred mercies; one of them is that by which creatures show mercy to each other, and ninety-nine are for the Day of Resurrection.","ch":"hadith"},{"id":"tirmidhi","t":"رواية الترمذي وسرد الأسماء","et":"Al-Tirmidhi's report and the listing of the names","x":"إِنَّ لِلَّهِ تَعَالَى تِسْعَةً وَتِسْعِينَ اسْمًا مِائَةً غَيْرَ وَاحِدَةٍ مَنْ أَحْصَاهَا دَخَلَ الْجَنَّةَ","src":[["tirmidhi","3507"]],"gr":"سرد الأسماء فيه ضعيف","dg":"الألباني: ضعيف؛ أحمد شاكر: ضعيف؛ زبير علي زئي: ضعيف","f":"ساق الترمذي بعد هذه الجملة عدّاً بالأسماء، وذهب كثير من المحققين إلى أن هذا السرد مدرج في الحديث وليس من كلام النبي ﷺ، وأن درجته ضعيفة كما في بيانات الكتاب؛ والعمدة أصل الحديث في الصحيحين. ولهذا لا يعتمد هذا القسم قائمة محددة بالعدد، بل يجمع الأسماء الواردة ألفاظها في القرآن.","ef":"After this sentence al-Tirmidhi gives a list of names. Many verifiers hold that this listing is an insertion in the hadith and not the Prophet's words, and its grading is weak as the book data shows; the reliable basis is the core hadith in the two Sahihs. For this reason this section does not rely on a fixed list, but gathers the names whose wording appears in the Quran.","en":"Allah has ninety-nine names; whoever enumerates them will enter Paradise.","ch":"hadith"}],"ay":{"1":"ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","2":"ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ","35":"هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا ثُمَّ ٱسۡتَوَىٰٓ إِلَى ٱلسَّمَآءِ فَسَوَّىٰهُنَّ سَبۡعَ سَمَٰوَٰتٖۚ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ","38":"قَالُواْ سُبۡحَٰنَكَ لَا عِلۡمَ لَنَآ إِلَّا مَا عَلَّمۡتَنَآۖ إِنَّكَ أَنتَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","43":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَٰتٖ فَتَابَ عَلَيۡهِۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ","121":"وَلِلَّهِ ٱلۡمَشۡرِقُ وَٱلۡمَغۡرِبُۚ فَأَيۡنَمَا تُوَلُّواْ فَثَمَّ وَجۡهُ ٱللَّهِۚ إِنَّ ٱللَّهَ وَٰسِعٌ عَلِيمٞ","123":"بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَإِذَا قَضَىٰٓ أَمۡرٗا فَإِنَّمَا يَقُولُ لَهُۥ كُن فَيَكُونُ","133":"وَإِذۡ يَرۡفَعُ إِبۡرَٰهِـۧمُ ٱلۡقَوَاعِدَ مِنَ ٱلۡبَيۡتِ وَإِسۡمَٰعِيلُ رَبَّنَا تَقَبَّلۡ مِنَّآۖ إِنَّكَ أَنتَ ٱلسَّمِيعُ ٱلۡعَلِيمُ","149":"وَكَذَٰلِكَ جَعَلۡنَٰكُمۡ أُمَّةٗ وَسَطٗا لِّتَكُونُواْ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيۡكُمۡ شَهِيدٗاۗ وَمَا جَعَلۡنَا ٱلۡقِبۡلَةَ ٱلَّتِي كُنتَ عَلَيۡهَآ إِلَّا لِنَعۡلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيۡهِۚ وَإِن كَانَتۡ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَٰنَكُمۡۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٞ رَّحِيمٞ","164":"۞ إِنَّ ٱلصَّفَا وَٱلۡمَرۡوَةَ مِن شَعَآئِرِ ٱللَّهِۖ فَمَنۡ حَجَّ ٱلۡبَيۡتَ أَوِ ٱعۡتَمَرَ فَلَا جُنَاحَ عَلَيۡهِ أَن يَطَّوَّفَ بِهِمَاۚ وَمَن تَطَوَّعَ خَيۡرٗا فَإِنَّ ٱللَّهَ شَاكِرٌ عَلِيمٌ","166":"إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَبَيَّنُواْ فَأُوْلَٰٓئِكَ أَتُوبُ عَلَيۡهِمۡ وَأَنَا ٱلتَّوَّابُ ٱلرَّحِيمُ","169":"وَإِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۖ لَّآ إِلَٰهَ إِلَّا هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ","179":"إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ بِهِۦ لِغَيۡرِ ٱللَّهِۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَلَآ إِثۡمَ عَلَيۡهِۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ","192":"وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌۖ أُجِيبُ دَعۡوَةَ ٱلدَّاعِ إِذَا دَعَانِۖ فَلۡيَسۡتَجِيبُواْ لِي وَلۡيُؤۡمِنُواْ بِي لَعَلَّهُمۡ يَرۡشُدُونَ","241":"وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا عَرَّضۡتُم بِهِۦ مِنۡ خِطۡبَةِ ٱلنِّسَآءِ أَوۡ أَكۡنَنتُمۡ فِيٓ أَنفُسِكُمۡۚ عَلِمَ ٱللَّهُ أَنَّكُمۡ سَتَذۡكُرُونَهُنَّ وَلَٰكِن لَّا تُوَاعِدُوهُنَّ سِرًّا إِلَّآ أَن تَقُولُواْ قَوۡلٗا مَّعۡرُوفٗاۚ وَلَا تَعۡزِمُواْ عُقۡدَةَ ٱلنِّكَاحِ حَتَّىٰ يَبۡلُغَ ٱلۡكِتَٰبُ أَجَلَهُۥۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ يَعۡلَمُ مَا فِيٓ أَنفُسِكُمۡ فَٱحۡذَرُوهُۚ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ غَفُورٌ حَلِيمٞ","253":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","261":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ","263":"ٱللَّهُ وَلِيُّ ٱلَّذِينَ ءَامَنُواْ يُخۡرِجُهُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۖ وَٱلَّذِينَ كَفَرُوٓاْ أَوۡلِيَآؤُهُمُ ٱلطَّٰغُوتُ يُخۡرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَٰتِۗ أُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ","269":"۞ قَوۡلٞ مَّعۡرُوفٞ وَمَغۡفِرَةٌ خَيۡرٞ مِّن صَدَقَةٖ يَتۡبَعُهَآ أَذٗىۗ وَٱللَّهُ غَنِيٌّ حَلِيمٞ","292":"لَا يُكَلِّفُ ٱللَّهُ نَفۡسًا إِلَّا وُسۡعَهَاۚ لَهَا مَا كَسَبَتۡ وَعَلَيۡهَا مَا ٱكۡتَسَبَتۡۗ رَبَّنَا لَا تُؤَاخِذۡنَآ إِن نَّسِينَآ أَوۡ أَخۡطَأۡنَاۚ رَبَّنَا وَلَا تَحۡمِلۡ عَلَيۡنَآ إِصۡرٗا كَمَا حَمَلۡتَهُۥ عَلَى ٱلَّذِينَ مِن قَبۡلِنَاۚ رَبَّنَا وَلَا تُحَمِّلۡنَا مَا لَا طَاقَةَ لَنَا بِهِۦۖ وَٱعۡفُ عَنَّا وَٱغۡفِرۡ لَنَا وَٱرۡحَمۡنَآۚ أَنتَ مَوۡلَىٰنَا فَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","294":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُ","298":"هُوَ ٱلَّذِي يُصَوِّرُكُمۡ فِي ٱلۡأَرۡحَامِ كَيۡفَ يَشَآءُۚ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","300":"رَبَّنَا لَا تُزِغۡ قُلُوبَنَا بَعۡدَ إِذۡ هَدَيۡتَنَا وَهَبۡ لَنَا مِن لَّدُنكَ رَحۡمَةًۚ إِنَّكَ أَنتَ ٱلۡوَهَّابُ","301":"رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوۡمٖ لَّا رَيۡبَ فِيهِۚ إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ","318":"قُلِ ٱللَّهُمَّ مَٰلِكَ ٱلۡمُلۡكِ تُؤۡتِي ٱلۡمُلۡكَ مَن تَشَآءُ وَتَنزِعُ ٱلۡمُلۡكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُۖ بِيَدِكَ ٱلۡخَيۡرُۖ إِنَّكَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","322":"يَوۡمَ تَجِدُ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ مِنۡ خَيۡرٖ مُّحۡضَرٗا وَمَا عَمِلَتۡ مِن سُوٓءٖ تَوَدُّ لَوۡ أَنَّ بَيۡنَهَا وَبَيۡنَهُۥٓ أَمَدَۢا بَعِيدٗاۗ وَيُحَذِّرُكُمُ ٱللَّهُ نَفۡسَهُۥۗ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ","389":"فِيهِ ءَايَٰتُۢ بَيِّنَٰتٞ مَّقَامُ إِبۡرَٰهِيمَۖ وَمَن دَخَلَهُۥ كَانَ ءَامِنٗاۗ وَلِلَّهِ عَلَى ٱلنَّاسِ حِجُّ ٱلۡبَيۡتِ مَنِ ٱسۡتَطَاعَ إِلَيۡهِ سَبِيلٗاۚ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ عَنِ ٱلۡعَٰلَمِينَ","465":"ٱلَّذِينَ قَالَ لَهُمُ ٱلنَّاسُ إِنَّ ٱلنَّاسَ قَدۡ جَمَعُواْ لَكُمۡ فَٱخۡشَوۡهُمۡ فَزَادَهُمۡ إِيمَٰنٗا وَقَالُواْ حَسۡبُنَا ٱللَّهُ وَنِعۡمَ ٱلۡوَكِيلُ","493":"يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا","498":"وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا","525":"وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا","577":"مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا","591":"فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا","618":"وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا","632":"وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا","639":"مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا","716":"وَأَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ مِنَ ٱلۡكِتَٰبِ وَمُهَيۡمِنًا عَلَيۡهِۖ فَٱحۡكُم بَيۡنَهُم بِمَآ أَنزَلَ ٱللَّهُۖ وَلَا تَتَّبِعۡ أَهۡوَآءَهُمۡ عَمَّا جَآءَكَ مِنَ ٱلۡحَقِّۚ لِكُلّٖ جَعَلۡنَا مِنكُمۡ شِرۡعَةٗ وَمِنۡهَاجٗاۚ وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن لِّيَبۡلُوَكُمۡ فِي مَآ ءَاتَىٰكُمۡۖ فَٱسۡتَبِقُواْ ٱلۡخَيۡرَٰتِۚ إِلَى ٱللَّهِ مَرۡجِعُكُمۡ جَمِيعٗا فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","785":"مَا قُلۡتُ لَهُمۡ إِلَّا مَآ أَمَرۡتَنِي بِهِۦٓ أَنِ ٱعۡبُدُواْ ٱللَّهَ رَبِّي وَرَبَّكُمۡۚ وَكُنتُ عَلَيۡهِمۡ شَهِيدٗا مَّا دُمۡتُ فِيهِمۡۖ فَلَمَّا تَوَفَّيۡتَنِي كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيۡهِمۡۚ وَأَنتَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","802":"قُلۡ أَغَيۡرَ ٱللَّهِ أَتَّخِذُ وَلِيّٗا فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَهُوَ يُطۡعِمُ وَلَا يُطۡعَمُۗ قُلۡ إِنِّيٓ أُمِرۡتُ أَنۡ أَكُونَ أَوَّلَ مَنۡ أَسۡلَمَۖ وَلَا تَكُونَنَّ مِنَ ٱلۡمُشۡرِكِينَ","806":"وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۚ وَهُوَ ٱلۡحَكِيمُ ٱلۡخَبِيرُ","849":"وَهُوَ ٱلۡقَاهِرُ فَوۡقَ عِبَادِهِۦۖ وَيُرۡسِلُ عَلَيۡكُمۡ حَفَظَةً حَتَّىٰٓ إِذَا جَآءَ أَحَدَكُمُ ٱلۡمَوۡتُ تَوَفَّتۡهُ رُسُلُنَا وَهُمۡ لَا يُفَرِّطُونَ","853":"قُلۡ هُوَ ٱلۡقَادِرُ عَلَىٰٓ أَن يَبۡعَثَ عَلَيۡكُمۡ عَذَابٗا مِّن فَوۡقِكُمۡ أَوۡ مِن تَحۡتِ أَرۡجُلِكُمۡ أَوۡ يَلۡبِسَكُمۡ شِيَعٗا وَيُذِيقَ بَعۡضَكُم بَأۡسَ بَعۡضٍۗ ٱنظُرۡ كَيۡفَ نُصَرِّفُ ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَفۡقَهُونَ","889":"بَدِيعُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَنَّىٰ يَكُونُ لَهُۥ وَلَدٞ وَلَمۡ تَكُن لَّهُۥ صَٰحِبَةٞۖ وَخَلَقَ كُلَّ شَيۡءٖۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٞ","890":"ذَٰلِكُمُ ٱللَّهُ رَبُّكُمۡۖ لَآ إِلَٰهَ إِلَّا هُوَۖ خَٰلِقُ كُلِّ شَيۡءٖ فَٱعۡبُدُوهُۚ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ وَكِيلٞ","891":"لَّا تُدۡرِكُهُ ٱلۡأَبۡصَٰرُ وَهُوَ يُدۡرِكُ ٱلۡأَبۡصَٰرَۖ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ","902":"أَفَغَيۡرَ ٱللَّهِ أَبۡتَغِي حَكَمٗا وَهُوَ ٱلَّذِيٓ أَنزَلَ إِلَيۡكُمُ ٱلۡكِتَٰبَ مُفَصَّلٗاۚ وَٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ يَعۡلَمُونَ أَنَّهُۥ مُنَزَّلٞ مِّن رَّبِّكَ بِٱلۡحَقِّۖ فَلَا تَكُونَنَّ مِنَ ٱلۡمُمۡتَرِينَ","952":"قُلۡ أَغَيۡرَ ٱللَّهِ أَبۡغِي رَبّٗا وَهُوَ رَبُّ كُلِّ شَيۡءٖۚ وَلَا تَكۡسِبُ كُلُّ نَفۡسٍ إِلَّا عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرۡجِعُكُمۡ فَيُنَبِّئُكُم بِمَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","1133":"وَلِلَّهِ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ فَٱدۡعُوهُ بِهَاۖ وَذَرُواْ ٱلَّذِينَ يُلۡحِدُونَ فِيٓ أَسۡمَٰٓئِهِۦۚ سَيُجۡزَوۡنَ مَا كَانُواْ يَعۡمَلُونَ","1199":"وَإِن تَوَلَّوۡاْ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَوۡلَىٰكُمۡۚ نِعۡمَ ٱلۡمَوۡلَىٰ وَنِعۡمَ ٱلنَّصِيرُ","1529":"فَإِن تَوَلَّوۡاْ فَقَدۡ أَبۡلَغۡتُكُم مَّآ أُرۡسِلۡتُ بِهِۦٓ إِلَيۡكُمۡۚ وَيَسۡتَخۡلِفُ رَبِّي قَوۡمًا غَيۡرَكُمۡ وَلَا تَضُرُّونَهُۥ شَيۡـًٔاۚ إِنَّ رَبِّي عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ","1533":"۞ وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ هُوَ أَنشَأَكُم مِّنَ ٱلۡأَرۡضِ وَٱسۡتَعۡمَرَكُمۡ فِيهَا فَٱسۡتَغۡفِرُوهُ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي قَرِيبٞ مُّجِيبٞ","1538":"فَلَمَّا جَآءَ أَمۡرُنَا نَجَّيۡنَا صَٰلِحٗا وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَمِنۡ خِزۡيِ يَوۡمِئِذٍۚ إِنَّ رَبَّكَ هُوَ ٱلۡقَوِيُّ ٱلۡعَزِيزُ","1545":"قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ","1562":"وَٱسۡتَغۡفِرُواْ رَبَّكُمۡ ثُمَّ تُوبُوٓاْ إِلَيۡهِۚ إِنَّ رَبِّي رَحِيمٞ وَدُودٞ","1616":"وَقَالَ ٱلَّذِي ٱشۡتَرَىٰهُ مِن مِّصۡرَ لِٱمۡرَأَتِهِۦٓ أَكۡرِمِي مَثۡوَىٰهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗاۚ وَكَذَٰلِكَ مَكَّنَّا لِيُوسُفَ فِي ٱلۡأَرۡضِ وَلِنُعَلِّمَهُۥ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ وَٱللَّهُ غَالِبٌ عَلَىٰٓ أَمۡرِهِۦ وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","1715":"عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِ ٱلۡكَبِيرُ ٱلۡمُتَعَالِ","1722":"قُلۡ مَن رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ قُلِ ٱللَّهُۚ قُلۡ أَفَٱتَّخَذۡتُم مِّن دُونِهِۦٓ أَوۡلِيَآءَ لَا يَمۡلِكُونَ لِأَنفُسِهِمۡ نَفۡعٗا وَلَا ضَرّٗاۚ قُلۡ هَلۡ يَسۡتَوِي ٱلۡأَعۡمَىٰ وَٱلۡبَصِيرُ أَمۡ هَلۡ تَسۡتَوِي ٱلظُّلُمَٰتُ وَٱلنُّورُۗ أَمۡ جَعَلُواْ لِلَّهِ شُرَكَآءَ خَلَقُواْ كَخَلۡقِهِۦ فَتَشَٰبَهَ ٱلۡخَلۡقُ عَلَيۡهِمۡۚ قُلِ ٱللَّهُ خَٰلِقُ كُلِّ شَيۡءٖ وَهُوَ ٱلۡوَٰحِدُ ٱلۡقَهَّٰرُ","1757":"وَقَالَ مُوسَىٰٓ إِن تَكۡفُرُوٓاْ أَنتُمۡ وَمَن فِي ٱلۡأَرۡضِ جَمِيعٗا فَإِنَّ ٱللَّهَ لَغَنِيٌّ حَمِيدٌ","1797":"يَوۡمَ تُبَدَّلُ ٱلۡأَرۡضُ غَيۡرَ ٱلۡأَرۡضِ وَٱلسَّمَٰوَٰتُۖ وَبَرَزُواْ لِلَّهِ ٱلۡوَٰحِدِ ٱلۡقَهَّارِ","1824":"وَإِنَّا لَنَحۡنُ نُحۡيِۦ وَنُمِيتُ وَنَحۡنُ ٱلۡوَٰرِثُونَ","1887":"إِنَّ رَبَّكَ هُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ","2029":"سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ","2072":"تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا","2138":"قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا","2184":"وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقۡتَدِرًا","2355":"ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰ","2415":"قُلۡنَا لَا تَخَفۡ إِنَّكَ أَنتَ ٱلۡأَعۡلَىٰ","2461":"فَتَعَٰلَى ٱللَّهُ ٱلۡمَلِكُ ٱلۡحَقُّۗ وَلَا تَعۡجَلۡ بِٱلۡقُرۡءَانِ مِن قَبۡلِ أَن يُقۡضَىٰٓ إِلَيۡكَ وَحۡيُهُۥۖ وَقُل رَّبِّ زِدۡنِي عِلۡمٗا","2600":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّهُۥ يُحۡيِ ٱلۡمَوۡتَىٰ وَأَنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","2611":"إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَادُواْ وَٱلصَّٰبِـِٔينَ وَٱلنَّصَٰرَىٰ وَٱلۡمَجُوسَ وَٱلَّذِينَ أَشۡرَكُوٓاْ إِنَّ ٱللَّهَ يَفۡصِلُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ","2634":"ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِم بِغَيۡرِ حَقٍّ إِلَّآ أَن يَقُولُواْ رَبُّنَا ٱللَّهُۗ وَلَوۡلَا دَفۡعُ ٱللَّهِ ٱلنَّاسَ بَعۡضَهُم بِبَعۡضٖ لَّهُدِّمَتۡ صَوَٰمِعُ وَبِيَعٞ وَصَلَوَٰتٞ وَمَسَٰجِدُ يُذۡكَرُ فِيهَا ٱسۡمُ ٱللَّهِ كَثِيرٗاۗ وَلَيَنصُرَنَّ ٱللَّهُ مَن يَنصُرُهُۥٓۚ إِنَّ ٱللَّهَ لَقَوِيٌّ عَزِيزٌ","2648":"وَلِيَعۡلَمَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ أَنَّهُ ٱلۡحَقُّ مِن رَّبِّكَ فَيُؤۡمِنُواْ بِهِۦ فَتُخۡبِتَ لَهُۥ قُلُوبُهُمۡۗ وَإِنَّ ٱللَّهَ لَهَادِ ٱلَّذِينَ ءَامَنُوٓاْ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","2652":"وَٱلَّذِينَ هَاجَرُواْ فِي سَبِيلِ ٱللَّهِ ثُمَّ قُتِلُوٓاْ أَوۡ مَاتُواْ لَيَرۡزُقَنَّهُمُ ٱللَّهُ رِزۡقًا حَسَنٗاۚ وَإِنَّ ٱللَّهَ لَهُوَ خَيۡرُ ٱلرَّٰزِقِينَ","2654":"۞ ذَٰلِكَۖ وَمَنۡ عَاقَبَ بِمِثۡلِ مَا عُوقِبَ بِهِۦ ثُمَّ بُغِيَ عَلَيۡهِ لَيَنصُرَنَّهُ ٱللَّهُۚ إِنَّ ٱللَّهَ لَعَفُوٌّ غَفُورٞ","2656":"ذَٰلِكَ بِأَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ وَأَنَّ مَا يَدۡعُونَ مِن دُونِهِۦ هُوَ ٱلۡبَٰطِلُ وَأَنَّ ٱللَّهَ هُوَ ٱلۡعَلِيُّ ٱلۡكَبِيرُ","2815":"يَوۡمَئِذٖ يُوَفِّيهِمُ ٱللَّهُ دِينَهُمُ ٱلۡحَقَّ وَيَعۡلَمُونَ أَنَّ ٱللَّهَ هُوَ ٱلۡحَقُّ ٱلۡمُبِينُ","2825":"۞ ٱللَّهُ نُورُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ مَثَلُ نُورِهِۦ كَمِشۡكَوٰةٖ فِيهَا مِصۡبَاحٌۖ ٱلۡمِصۡبَاحُ فِي زُجَاجَةٍۖ ٱلزُّجَاجَةُ كَأَنَّهَا كَوۡكَبٞ دُرِّيّٞ يُوقَدُ مِن شَجَرَةٖ مُّبَٰرَكَةٖ زَيۡتُونَةٖ لَّا شَرۡقِيَّةٖ وَلَا غَرۡبِيَّةٖ يَكَادُ زَيۡتُهَا يُضِيٓءُ وَلَوۡ لَمۡ تَمۡسَسۡهُ نَارٞۚ نُّورٌ عَلَىٰ نُورٖۚ يَهۡدِي ٱللَّهُ لِنُورِهِۦ مَن يَشَآءُۚ وَيَضۡرِبُ ٱللَّهُ ٱلۡأَمۡثَٰلَ لِلنَّاسِۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ","2885":"وَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا مِّنَ ٱلۡمُجۡرِمِينَۗ وَكَفَىٰ بِرَبِّكَ هَادِيٗا وَنَصِيرٗا","3198":"قَالَ ٱلَّذِي عِندَهُۥ عِلۡمٞ مِّنَ ٱلۡكِتَٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبۡلَ أَن يَرۡتَدَّ إِلَيۡكَ طَرۡفُكَۚ فَلَمَّا رَءَاهُ مُسۡتَقِرًّا عِندَهُۥ قَالَ هَٰذَا مِن فَضۡلِ رَبِّي لِيَبۡلُوَنِيٓ ءَأَشۡكُرُ أَمۡ أَكۡفُرُۖ وَمَن شَكَرَ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ رَبِّي غَنِيّٞ كَرِيمٞ","3494":"لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ إِنَّ ٱللَّهَ هُوَ ٱلۡغَنِيُّ ٱلۡحَمِيدُ","3495":"وَلَوۡ أَنَّمَا فِي ٱلۡأَرۡضِ مِن شَجَرَةٍ أَقۡلَٰمٞ وَٱلۡبَحۡرُ يَمُدُّهُۥ مِنۢ بَعۡدِهِۦ سَبۡعَةُ أَبۡحُرٖ مَّا نَفِدَتۡ كَلِمَٰتُ ٱللَّهِۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ","3571":"ٱلَّذِينَ يُبَلِّغُونَ رِسَٰلَٰتِ ٱللَّهِ وَيَخۡشَوۡنَهُۥ وَلَا يَخۡشَوۡنَ أَحَدًا إِلَّا ٱللَّهَۗ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا","3575":"هُوَ ٱلَّذِي يُصَلِّي عَلَيۡكُمۡ وَمَلَٰٓئِكَتُهُۥ لِيُخۡرِجَكُم مِّنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِۚ وَكَانَ بِٱلۡمُؤۡمِنِينَ رَحِيمٗا","3626":"وَمَا كَانَ لَهُۥ عَلَيۡهِم مِّن سُلۡطَٰنٍ إِلَّا لِنَعۡلَمَ مَن يُؤۡمِنُ بِٱلۡأٓخِرَةِ مِمَّنۡ هُوَ مِنۡهَا فِي شَكّٖۗ وَرَبُّكَ عَلَىٰ كُلِّ شَيۡءٍ حَفِيظٞ","3631":"قُلۡ يَجۡمَعُ بَيۡنَنَا رَبُّنَا ثُمَّ يَفۡتَحُ بَيۡنَنَا بِٱلۡحَقِّ وَهُوَ ٱلۡفَتَّاحُ ٱلۡعَلِيمُ","3660":"ٱلۡحَمۡدُ لِلَّهِ فَاطِرِ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ جَاعِلِ ٱلۡمَلَٰٓئِكَةِ رُسُلًا أُوْلِيٓ أَجۡنِحَةٖ مَّثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۚ يَزِيدُ فِي ٱلۡخَلۡقِ مَا يَشَآءُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","3689":"لِيُوَفِّيَهُمۡ أُجُورَهُمۡ وَيَزِيدَهُم مِّن فَضۡلِهِۦٓۚ إِنَّهُۥ غَفُورٞ شَكُورٞ","3785":"أَوَلَيۡسَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِقَٰدِرٍ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۚ بَلَىٰ وَهُوَ ٱلۡخَلَّٰقُ ٱلۡعَلِيمُ","3862":"وَلَقَدۡ نَادَىٰنَا نُوحٞ فَلَنِعۡمَ ٱلۡمُجِيبُونَ","3978":"أَمۡ عِندَهُمۡ خَزَآئِنُ رَحۡمَةِ رَبِّكَ ٱلۡعَزِيزِ ٱلۡوَهَّابِ","4035":"رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلۡعَزِيزُ ٱلۡغَفَّٰرُ","4061":"لَّوۡ أَرَادَ ٱللَّهُ أَن يَتَّخِذَ وَلَدٗا لَّٱصۡطَفَىٰ مِمَّا يَخۡلُقُ مَا يَشَآءُۚ سُبۡحَٰنَهُۥۖ هُوَ ٱللَّهُ ٱلۡوَٰحِدُ ٱلۡقَهَّارُ","4093":"أَلَيۡسَ ٱللَّهُ بِكَافٍ عَبۡدَهُۥۖ وَيُخَوِّفُونَكَ بِٱلَّذِينَ مِن دُونِهِۦۚ وَمَن يُضۡلِلِ ٱللَّهُ فَمَا لَهُۥ مِنۡ هَادٖ","4110":"۞ قُلۡ يَٰعِبَادِيَ ٱلَّذِينَ أَسۡرَفُواْ عَلَىٰٓ أَنفُسِهِمۡ لَا تَقۡنَطُواْ مِن رَّحۡمَةِ ٱللَّهِۚ إِنَّ ٱللَّهَ يَغۡفِرُ ٱلذُّنُوبَ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ","4135":"غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوۡبِ شَدِيدِ ٱلۡعِقَابِ ذِي ٱلطَّوۡلِۖ لَآ إِلَٰهَ إِلَّا هُوَۖ إِلَيۡهِ ٱلۡمَصِيرُ","4144":"ذَٰلِكُم بِأَنَّهُۥٓ إِذَا دُعِيَ ٱللَّهُ وَحۡدَهُۥ كَفَرۡتُمۡ وَإِن يُشۡرَكۡ بِهِۦ تُؤۡمِنُواْۚ فَٱلۡحُكۡمُ لِلَّهِ ٱلۡعَلِيِّ ٱلۡكَبِيرِ","4197":"هُوَ ٱلۡحَيُّ لَآ إِلَٰهَ إِلَّا هُوَ فَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۗ ٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ","4271":"أَلَآ إِنَّهُمۡ فِي مِرۡيَةٖ مِّن لِّقَآءِ رَبِّهِمۡۗ أَلَآ إِنَّهُۥ بِكُلِّ شَيۡءٖ مُّحِيطُۢ","4275":"لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ","4280":"أَمِ ٱتَّخَذُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۖ فَٱللَّهُ هُوَ ٱلۡوَلِيُّ وَهُوَ يُحۡيِ ٱلۡمَوۡتَىٰ وَهُوَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","4282":"فَاطِرُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَمِنَ ٱلۡأَنۡعَٰمِ أَزۡوَٰجٗا يَذۡرَؤُكُمۡ فِيهِۚ لَيۡسَ كَمِثۡلِهِۦ شَيۡءٞۖ وَهُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ","4542":"أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","4732":"إِنَّ ٱللَّهَ هُوَ ٱلرَّزَّاقُ ذُو ٱلۡقُوَّةِ ٱلۡمَتِينُ","4762":"إِنَّا كُنَّا مِن قَبۡلُ نَدۡعُوهُۖ إِنَّهُۥ هُوَ ٱلۡبَرُّ ٱلرَّحِيمُ","4887":"كَذَّبُواْ بِـَٔايَٰتِنَا كُلِّهَا فَأَخَذۡنَٰهُمۡ أَخۡذَ عَزِيزٖ مُّقۡتَدِرٍ","4901":"ٱلرَّحۡمَٰنُ","4927":"وَيَبۡقَىٰ وَجۡهُ رَبِّكَ ذُو ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ","4978":"تَبَٰرَكَ ٱسۡمُ رَبِّكَ ذِي ٱلۡجَلَٰلِ وَٱلۡإِكۡرَامِ","5074":"فَسَبِّحۡ بِٱسۡمِ رَبِّكَ ٱلۡعَظِيمِ","5077":"هُوَ ٱلۡأَوَّلُ وَٱلۡأٓخِرُ وَٱلظَّٰهِرُ وَٱلۡبَاطِنُۖ وَهُوَ بِكُلِّ شَيۡءٍ عَلِيمٌ","5147":"هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَۖ عَٰلِمُ ٱلۡغَيۡبِ وَٱلشَّهَٰدَةِۖ هُوَ ٱلرَّحۡمَٰنُ ٱلرَّحِيمُ","5148":"هُوَ ٱللَّهُ ٱلَّذِي لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡمَلِكُ ٱلۡقُدُّوسُ ٱلسَّلَٰمُ ٱلۡمُؤۡمِنُ ٱلۡمُهَيۡمِنُ ٱلۡعَزِيزُ ٱلۡجَبَّارُ ٱلۡمُتَكَبِّرُۚ سُبۡحَٰنَ ٱللَّهِ عَمَّا يُشۡرِكُونَ","5149":"هُوَ ٱللَّهُ ٱلۡخَٰلِقُ ٱلۡبَارِئُ ٱلۡمُصَوِّرُۖ لَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ يُسَبِّحُ لَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","5177":"يُسَبِّحُ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ ٱلۡمَلِكِ ٱلۡقُدُّوسِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ","5215":"إِن تُقۡرِضُواْ ٱللَّهَ قَرۡضًا حَسَنٗا يُضَٰعِفۡهُ لَكُمۡ وَيَغۡفِرۡ لَكُمۡۚ وَٱللَّهُ شَكُورٌ حَلِيمٌ","5254":"أَلَا يَعۡلَمُ مَنۡ خَلَقَ وَهُوَ ٱللَّطِيفُ ٱلۡخَبِيرُ","5428":"فَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا","5834":"يَٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ","5922":"وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ","5923":"ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ","5948":"سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى","6108":"ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ","6221":"قُلۡ هُوَ ٱللَّهُ أَحَدٌ","6222":"ٱللَّهُ ٱلصَّمَدُ"},"nn":88,"nay":124};
